    function prevoirReecriture() {
      if (reecriturePrevue) return;
      reecriturePrevue = true;

      Promise.resolve().then(function () { reecriturePrevue = false; reecrireTout(); });
    }
    function surveillerFeuilles() {
      reecrireTout();
      new MutationObserver(function (ms) {
        for (let i = 0; i < ms.length; i++) {
          const m = ms[i];
          if (m.target && m.target.nodeName === 'STYLE') { prevoirReecriture(); return; }
          const a = m.addedNodes;
          for (let j = 0; j < a.length; j++) {
            const nn = a[j].nodeName;
            if (nn === 'STYLE' || nn === 'LINK') { prevoirReecriture(); return; }
          }
        }
      }).observe(document, { childList: true, subtree: true });

      document.addEventListener('load', function (e) { if (e.target && e.target.nodeName === 'LINK') reecrireFeuille(e.target.sheet); }, true);
    }

