  function masquesDansMenu() {
    if (!menuReel) return 0;
    return itemsNotif(menuReel).filter(function (i) { return masquees.indexOf(cleNotif(i)) !== -1; }).length;
  }

  function preparerItems(c) {
    itemsNotif(c).forEach(function (item) {
      const cle = cleNotif(item);
      if (masquees.indexOf(cle) !== -1) { item.style.setProperty('display', 'none', 'important'); return; }
      item.style.setProperty('position', 'relative', 'important');
      const x = document.createElement('span');
      x.setAttribute('data-np-masquer-notif', '');
      x.textContent = '✕';
      x.title = 'Masquer cette notification (chez toi seulement)';
      x.style.cssText = 'position:absolute;top:6px;right:6px;width:24px;height:24px;display:flex;align-items:center;justify-content:center;border-radius:5px;' +
        'cursor:pointer;font:bold 16px/1 sans-serif;color:var(--text-color,#C5C8C6);opacity:.5;z-index:1;';
      x.addEventListener('mouseenter', function () { x.style.opacity = '1'; x.style.background = 'rgba(127,127,127,.25)'; });
      x.addEventListener('mouseleave', function () { x.style.opacity = '.45'; x.style.background = ''; });
      x.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        if (masquees.indexOf(cle) === -1) masquees.push(cle);
        enregistrerMasquees();
        item.style.setProperty('display', 'none', 'important');
        majLigneMasquees();
      });
      item.appendChild(x);
    });
    majLigneMasquees();
  }
  let ligneMasquees = null;
  function majLigneMasquees() {
    if (!ligneMasquees || !ligneMasquees.isConnected) return;
    const n = masquesDansMenu();
    const visibles = menuReel ? itemsNotif(menuReel).length - n : 0;
    const t = ligneMasquees.querySelector('[data-np-nb-masquees]');
    if (t) t.textContent = n ? n + ' notification' + (n > 1 ? 's' : '') + ' masquée' + (n > 1 ? 's' : '') + ' ·' : '';
    const re = ligneMasquees.querySelector('[data-np-reafficher]');
    if (re) re.style.display = n ? '' : 'none';
    const b = ligneMasquees.querySelector('[data-np-tout-fermer]');
    if (b) { b.disabled = !visibles; b.style.opacity = visibles ? '' : '.45'; b.style.cursor = visibles ? 'pointer' : 'default'; }
  }

  function toutFermerForum() {
    if (!menuReel) return;
    itemsNotif(menuReel).forEach(function (i) { const k = cleNotif(i); if (masquees.indexOf(k) === -1) masquees.push(k); });
    enregistrerMasquees();
    dessinerCopie(true);
  }

  const STYLE_COPIE = {
    position: 'static', inset: 'auto', transform: 'none', transition: 'none', animation: 'none', margin: '0', width: 'auto',
    'max-width': 'none', 'min-width': '0', 'box-shadow': 'none', border: 'none', 'border-radius': '0 0 8px 8px',
    visibility: 'visible', opacity: '1', 'z-index': 'auto', 'overflow-y': 'auto', 'pointer-events': 'auto',
  };
  const STYLE_ANCETRE = 'display:block!important;position:static!important;inset:auto!important;width:auto!important;height:auto!important;' +
    'min-width:0!important;min-height:0!important;max-width:none!important;max-height:none!important;margin:0!important;padding:0!important;' +
    'border:0!important;background:transparent!important;box-shadow:none!important;transform:none!important;overflow:visible!important;' +
    'visibility:visible!important;opacity:1!important;pointer-events:auto!important;';

  function dessinerCopie(forcer) {
    if (!menuReel || !placeForum || !placeForum.isConnected) return;
    const signature = menuReel.innerHTML;
    if (!forcer && copieMenu && copieMenu.isConnected && signature === signatureCopie) return;

    if (appuiCopie && !forcer) {
      if (!attenteCopie) attenteCopie = requestAnimationFrame(function () { attenteCopie = null; dessinerCopie(false); });
      return;
    }
    signatureCopie = signature;

    const defil = [];
    if (copieMenu) {
      [copieMenu].concat(Array.from(copieMenu.querySelectorAll('*'))).forEach(function (e) {
        if (e.scrollTop) defil.push([cheminDe(e, copieMenu), e.scrollTop]);
      });
    }
    const c = menuReel.cloneNode(true);
    c.removeAttribute('data-np-menu-cache');
    c.removeAttribute('id');
    c.setAttribute('data-np-copie-menu', '');
    Object.keys(STYLE_COPIE).forEach(function (k) { c.style.setProperty(k, STYLE_COPIE[k], 'important'); });
    const haut = panneau ? placeForum.getBoundingClientRect().top - panneau.getBoundingClientRect().top : 40;
    c.style.setProperty('max-height', Math.max(150, window.innerHeight * 0.7 - haut - 4) + 'px', 'important');
    const titre = titreDans(c);
    if (titre) titre.style.setProperty('display', 'none', 'important');
    preparerItems(c);
    c.addEventListener('click', relayerClic, true);
    c.addEventListener('scroll', relayerDefilement, true);
    c.addEventListener('mousedown', function () { appuiCopie = true; }, true);

    let racine = c;
    for (let a = menuReel.parentElement; a && a !== document.body && a !== document.documentElement; a = a.parentElement) {
      const copieAncetre = document.createElement(a.tagName.toLowerCase() === 'body' ? 'div' : a.tagName.toLowerCase());
      Array.from(a.attributes).forEach(function (x) {
        if (x.name === 'class' || x.name.indexOf('data-v-') === 0) copieAncetre.setAttribute(x.name, x.value);
      });
      copieAncetre.setAttribute('style', STYLE_ANCETRE);
      copieAncetre.appendChild(racine);
      racine = copieAncetre;
    }
    placeForum.textContent = '';
    placeForum.style.cssText = '';
    placeForum.appendChild(racine);
    copieMenu = c;
    defil.forEach(function (d) {
      const e = d[0] && suivreChemin(c, d[0]);
      if (e) e.scrollTop = d[1];
    });
  }

  document.addEventListener('mouseup', function () { appuiCopie = false; }, true);

  function relayerClic(e) {
    if (!menuReel || !copieMenu) return;
    if (e.target.closest && e.target.closest('[data-np-masquer-notif]')) return;
    e.preventDefault();
    e.stopPropagation();
    const chemin = cheminDe(e.target, copieMenu);
    const cible = chemin && suivreChemin(menuReel, chemin);
    if (!cible) return;
    clicDansMenu = Date.now();
    cible.dispatchEvent(new MouseEvent('click', {
      bubbles: true, cancelable: true, button: e.button,
      ctrlKey: e.ctrlKey, metaKey: e.metaKey, shiftKey: e.shiftKey, altKey: e.altKey,
    }));
  }

  function relayerDefilement(e) {
    if (!menuReel || !copieMenu || !(e.target instanceof Element)) return;
    const chemin = cheminDe(e.target, copieMenu);
    const reel = chemin && suivreChemin(menuReel, chemin);
    if (reel) reel.scrollTop = e.target.scrollTop;
  }

  function arreterOuverture() {
    if (guetteurOuverture) { guetteurOuverture.disconnect(); guetteurOuverture = null; }
    clearTimeout(minuteurOuverture);
    minuteurOuverture = null;
  }

  function ouvrirForum() {
    if (menuReel && menuReel.isConnected) return;
    const deja = trouverMenuForum();
    if (deja) { etatForum = ''; brancherMenu(deja); return; }
    arreterOuverture();

    guetteurOuverture = new MutationObserver(function () {
      const m = trouverMenuForum();
      if (!m) return;
      arreterOuverture();
      etatForum = '';
      if (panneau && ongletPanneau === 'forum') { brancherMenu(m); dessinerPanneau(); }
      else { m.setAttribute('data-np-menu-cache', ''); fermerMenuSite(m, function () { m.removeAttribute('data-np-menu-cache'); }); }
    });
    guetteurOuverture.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class', 'style'] });
    if (!cliquerCloche()) { arreterOuverture(); etatForum = 'echec'; return; }
    if (guetteurOuverture) {
      etatForum = 'chargement';
      minuteurOuverture = setTimeout(function () {
        arreterOuverture();
        etatForum = 'echec';
        appliquerCloche();
        if (panneau && ongletPanneau === 'forum') dessinerPanneau();
      }, 2500);
    }
  }

  let etatToutLireForum = '';
  function baseApi() {
    try {
      const vus = performance.getEntriesByType('resource').map(function (e) { return e.name; });
      for (let i = vus.length - 1; i >= 0; i--) {
        const m = vus[i].match(/^(https?:\/\/[^/]+(?:\/[^?#]*?)?\/)(?:me\/notifications\/|mp\/unread-count\/|api\/current-user\/)/);
        if (m && m[1].indexOf(location.host) !== -1) return m[1];
      }
    } catch (e) {}
    return location.origin + '/nanachannel/';
  }
  function jetonCsrf() {
    const m = document.cookie.match(/(?:^|;\s*)csrftoken=([^;]+)/);
    return m ? decodeURIComponent(m[1]) : '';
  }
  async function toutLireForum() {
    etatToutLireForum = 'en cours';
    if (panneau && ongletPanneau === 'forum') dessinerPanneau();
    const entetes = { Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest' };
    const jeton = jetonCsrf();
    if (jeton) entetes['X-CSRFToken'] = jeton;
    let ok = false;
    const bases = [baseApi()];
    if (bases[0] !== location.origin + '/nanachannel/') bases.push(location.origin + '/nanachannel/');
    for (let i = 0; i < bases.length && !ok; i++) {
      try {
        const r = await fetch(bases[i] + 'me/notifications/', { method: 'PATCH', credentials: 'include', headers: entetes });
        ok = r.ok;
        if (!ok) console.warn('[Notifications+] Tout lire : ' + bases[i] + 'me/notifications/ -> HTTP ' + r.status);
      } catch (e) { console.warn('[Notifications+] Tout lire : ' + e); }
    }
    etatToutLireForum = ok ? 'ok' : 'echec';
    setTimeout(function () { etatToutLireForum = ''; if (panneau && ongletPanneau === 'forum') dessinerPanneau(); }, 3000);
    if (ok) masqueCompteSite = compteSite();

    if (panneau && ongletPanneau === 'forum') {
      debrancherMenu(true);
      setTimeout(function () { if (panneau && ongletPanneau === 'forum') { panneau.removeAttribute('data-np-forum-vu'); dessinerPanneau(); } }, 300);
    }
    majAffichage();
  }

  function changerOnglet(o) {
    if (ongletPanneau === 'forum' && o !== 'forum') debrancherMenu(true);
    if (o === 'forum' && panneau) panneau.removeAttribute('data-np-forum-vu');
    ongletPanneau = o;
    dessinerPanneau();
  }

  function dessinerForum(corps) {
    corps.style.padding = '0';
    if (etatForum === 'echec') {
      const boite = el('div', 'padding:14px 12px;line-height:1.5;');
      boite.appendChild(el('div', 'opacity:.8;', 'Le menu de notifications du forum n\'a pas pu être affiché ici. La cloche du forum est réaffichée en attendant (son menu s\'ouvre à sa place habituelle).'));
      const b = el('button', CSS_BTN + 'margin-top:8px;', 'Réessayer');
      b.type = 'button';
      b.addEventListener('click', function () { etatForum = ''; appliquerCloche(); changerOnglet('forum'); });
      boite.appendChild(b);
      corps.appendChild(boite);
      return;
    }

    const nb = compteSite();
    barreToutLire(corps, etatToutLireForum !== 'en cours', toutLireForum,
      etatToutLireForum === 'en cours' ? 'Marquage…'
        : etatToutLireForum === 'ok' ? '✓ Tout est marqué comme lu'
        : etatToutLireForum === 'echec' ? '✗ Échec, réessaie'
        : nb ? nb + ' non lue' + (nb > 1 ? 's' : '') : 'Marque toutes les notifications du forum comme lues');
    ligneMasquees = el('div', 'display:flex;align-items:center;gap:6px;padding:0 10px 6px;font-size:11px;');
    const nbM = el('span', 'opacity:.6;');
    nbM.setAttribute('data-np-nb-masquees', '');
    ligneMasquees.appendChild(nbM);
    const reaff = el('span', 'cursor:pointer;text-decoration:underline;opacity:.8;', 'Réafficher');
    reaff.setAttribute('data-np-reafficher', '');
    reaff.addEventListener('click', function () {
      const presentes = menuReel ? itemsNotif(menuReel).map(cleNotif) : [];
      masquees = masquees.filter(function (k) { return presentes.indexOf(k) === -1; });
      enregistrerMasquees();
      dessinerCopie(true);
    });
    ligneMasquees.appendChild(reaff);
    ligneMasquees.appendChild(el('span', 'flex:1;'));
    const bFermer = el('button', CSS_BTN, '✕ Tout fermer');
    bFermer.type = 'button';
    bFermer.title = 'Masque toutes les notifications du forum (chez toi seulement)';
    bFermer.setAttribute('data-np-tout-fermer', '');
    bFermer.addEventListener('click', function () { if (!bFermer.disabled) toutFermerForum(); });
    ligneMasquees.appendChild(bFermer);
    corps.appendChild(ligneMasquees);
    majLigneMasquees();
    placeForum = el('div', '');
    corps.appendChild(placeForum);
    if (menuReel && menuReel.isConnected) { copieMenu = null; dessinerCopie(true); return; }
    if (etatForum !== 'chargement') {
      if (panneau.getAttribute('data-np-forum-vu')) {

        placeForum.style.cssText = 'padding:14px 12px;';
        const b = el('button', CSS_BTN, 'Rouvrir le menu du forum');
        b.type = 'button';
        b.addEventListener('click', function () { changerOnglet('forum'); });
        placeForum.appendChild(b);
        placeForum = null;
        return;
      }
      panneau.setAttribute('data-np-forum-vu', '1');
      ouvrirForum();
      if (etatForum === 'echec') { dessinerPanneau(); return; }
      if (menuReel) return;
    }
    placeForum.style.cssText = 'height:120px;display:flex;align-items:center;justify-content:center;opacity:.6;';
    placeForum.textContent = 'Chargement…';
  }

  const debutScript = Date.now();

  function assurerBouton() {
    const cloche = trouverClocheSite();
    const zone = cloche ? zoneCloche() : null;
    const mode = zone ? 'cloche' : 'mp';
    if (bouton && bouton.isConnected && bouton.getAttribute('data-np-mode') === mode) {
      if (mode === 'mp') return;
      const ext = enveloppeExterne();
      if (ext.previousElementSibling === zone) return;
    }
    let modele = null;
    let reference = null;
    if (mode === 'cloche') {
      modele = cliquableCloche();
    } else {

      if (Date.now() - debutScript < 3000) return;
      reference = document.querySelector('header a.bouton-mp, header .bouton-mp');
      if (!reference) return;
      modele = reference;
    }
    if (bouton) { const ancien = enveloppeExterne(); ancien.remove(); }

    const balise = modele.tagName === 'BUTTON' ? 'button' : (modele.tagName === 'A' ? 'a' : modele.tagName.toLowerCase());
    bouton = document.createElement(balise === 'svg' ? 'span' : balise);
    Array.from(modele.attributes).forEach(function (x) {

      if (x.name === 'class' || x.name === 'style' || x.name.indexOf('data-v-') === 0) bouton.setAttribute(x.name, x.value);
    });
    bouton.setAttribute('data-np-bouton', '');
    bouton.setAttribute('data-np-mode', mode);
    bouton.setAttribute('role', 'button');
    if (balise === 'a') bouton.href = '#';
    if (balise === 'button') bouton.type = 'button';
    bouton.title = 'Notifications+';
    bouton.style.position = 'relative';
    const media = R().styleCloche === 'perso' ? lireMedia() : '';
    const taille = cloche ? Math.round(cloche.getBoundingClientRect().width || parseFloat(cloche.getAttribute('width')) || 22) : 22;
    bouton._npBase = taille;
    if (media) {
      bouton.appendChild(elementMedia(media, taille));
    } else if (mode === 'cloche' && cloche && cloche.tagName.toLowerCase() === 'svg') {

      const icone = cloche.cloneNode(true);
      if (R().styleCloche !== 'site') ajouterPlus(icone);
      bouton.appendChild(icone);
    } else {
      bouton.innerHTML = SVG_CLOCHE;
      if (R().styleCloche !== 'site') ajouterPlus(bouton.querySelector('svg'));
    }
    bouton._npIcone = bouton.querySelector('svg, [data-np-media]');
    appliquerTailleCloche();

    pastille = document.createElement('span');
    pastille.setAttribute('data-np-pastilles', '');

    pastille.style.cssText = 'position:absolute;right:100%;top:50%;transform:translateY(-50%);margin-right:3px;display:none;flex-direction:column;align-items:flex-end;gap:1px;pointer-events:none;z-index:1;';
    bouton.appendChild(pastille);
    bouton.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      if (panneau && panneau.isConnected) fermerPanneau(); else ouvrirPanneau();
    });

    if (mode === 'cloche') {

      let racine = bouton;
      for (let a = modele.parentElement; a && zone.contains(a); a = a.parentElement) {
        const env = document.createElement(a.tagName.toLowerCase());
        Array.from(a.attributes).forEach(function (x) {
          if (x.name === 'class' || x.name === 'style' || x.name.indexOf('data-v-') === 0) env.setAttribute(x.name, x.value);
        });
        env.setAttribute('data-np-enveloppe', '');
        env.appendChild(racine);
        racine = env;
        if (a === zone) break;
      }
      zone.after(racine);
    } else {
      reference.parentElement.insertBefore(bouton, reference);
    }
    majAffichage();
    appliquerCloche();
  }

  function elementMedia(lien, taille) {
    const video = /^data:video\//i.test(lien) || /\.(mp4|webm|mov|m4v)(?:[?#]|$)/i.test(lien);
    const m = document.createElement(video ? 'video' : 'img');
    if (video) { m.muted = true; m.loop = true; m.autoplay = true; m.playsInline = true; m.setAttribute('muted', ''); }
    else m.alt = '';
    m.src = lien;
    m.setAttribute('data-np-media', '');
    m.style.cssText = 'display:block;width:' + taille + 'px;height:' + taille + 'px;object-fit:contain;pointer-events:none;';
    return m;
  }

  function appliquerTailleCloche() {
    const i = bouton && bouton._npIcone;
    if (!i) return;

    const k = Math.max(50, Math.min(TAILLE_MAX, Number(R().tailleCloche) || 100)) / 100;
    i.style.transformOrigin = 'center';
    i.style.transform = k === 1 ? '' : 'scale(' + k + ')';
    placerColonnePastilles();
  }
  const TAILLE_MAX = 180;

  function coteCloche() {
    const a = document.documentElement.getAttribute('data-notif-pos');
    if (a === 'left' || a === 'right') return a;
    if (!bouton || !bouton.isConnected) return 'right';
    const r = bouton.getBoundingClientRect();
    return r.left + r.width / 2 < window.innerWidth / 2 ? 'left' : 'right';
  }
  function placerColonnePastilles() {
    if (!pastille) return;
    const gauche = coteCloche() === 'left';

    let videG = 0;
    let videD = 0;
    const i = bouton && bouton._npIcone;
    if (i && bouton.isConnected) {
      const rb = bouton.getBoundingClientRect();
      const ri = i.getBoundingClientRect();
      if (ri.width) { videG = Math.max(0, ri.left - rb.left); videD = Math.max(0, rb.right - ri.right); }
    }
    pastille.style.right = gauche ? 'auto' : 'calc(100% - ' + Math.round(videG) + 'px)';
    pastille.style.left = gauche ? 'calc(100% - ' + Math.round(videD) + 'px)' : 'auto';
    pastille.style.marginRight = gauche ? '0' : '2px';
    pastille.style.marginLeft = gauche ? '2px' : '0';
    pastille.style.alignItems = gauche ? 'flex-start' : 'flex-end';
  }

  let testPastilles = null;
  function testerPastilles() {
    clearTimeout(testPastilles && testPastilles.minuteur);
    testPastilles = { minuteur: setTimeout(function () { testPastilles = null; majPastilles(); majPastilleEnveloppe(); majTestFil(); }, 5000) };
    majTestFil();
    majPastilles();
    majPastilleEnveloppe();
  }

  function reconstruireBouton() {
    if (bouton) { enveloppeExterne().remove(); bouton = null; pastille = null; }
    assurerBouton();
  }

  function enveloppeExterne() {
    let e = bouton;
    while (e && e.parentElement && e.parentElement.hasAttribute('data-np-enveloppe')) e = e.parentElement;
    return e;
  }

  function totalNonCoupe() {
    const t = nouveauxParType();
    return (coupe('messages') ? 0 : (clocheCachee() ? compteSite() : 0)) + (coupe('topic') ? 0 : t.topic) + (coupe('favori') ? 0 : t.favori) + (coupe('mp') ? 0 : compteMp()) + (coupe('fil') ? 0 : compteFil());
  }
  function totalAffiche() {
    return totalNouveaux() + (clocheCachee() ? compteSite() : 0);
  }

  function majAffichage() {
    majDndMp();
    majDndFil();
    majPastilleEnveloppe();
    const total = totalAffiche();
    majPastilles(total);
    majTitreOnglet();
    if (panneau && panneau.isConnected) dessinerPanneau();
  }
  function majPastilles(total) {
    if (total == null) total = totalAffiche();
    if (pastille) {
      const t = nouveauxParType();

      let parts = [['messages', clocheCachee() ? compteSite() : 0], ['topic', t.topic], ['favori', t.favori]];
      const filCloche = filPresent() && modePastilleFil() === 'colonne';
      if (filCloche) { parts.push(['fil', compteFil()]); if (!coupe('fil')) total += compteFil(); }
      if (testPastilles) { parts = [['messages', 3], ['topic', 1], ['favori', 12]].concat(filCloche ? [['fil', 2]] : []); total = 18; }
      pastille.textContent = '';
      if (R().dnd && !testPastilles) {

        const lune = el('span', 'font-size:11px;line-height:15px;filter:drop-shadow(0 0 1px rgba(0,0,0,.6));', '🌙');
        lune.setAttribute('data-np-lune', '');
        pastille.appendChild(lune);
        parts = parts.filter(function (x) { return !coupe(x[0]); });
        total = 1;
      }
      parts.filter(function (x) { return x[1]; }).forEach(function (x) {
        const b = document.createElement('span');
        b.setAttribute('data-np-pastille', x[0]);
        b.style.cssText = 'min-width:15px;height:15px;padding:0 4px;box-sizing:border-box;border-radius:8px;font:bold 10px/15px sans-serif;text-align:center;white-space:nowrap;' +
          'box-shadow:0 0 0 1.5px rgba(0,0,0,.35);' + stylePastille(x[0]);
        b.textContent = x[1] > 99 ? '99+' : String(x[1]);
        pastille.appendChild(b);
      });
      pastille.style.display = total ? 'flex' : 'none';
      placerColonnePastilles();
    }
    majPastilleCoinFil();
  }

  let titreEnCours = false;
  function majTitreOnglet() {
    const base = document.title.replace(/^\(\d+\+?\)\s*/, '');

    let total = 0;
    if (R().compteurOnglet) total = lu.topic ? (lu.dernier ? nbNonLusDansPage(lu.dernier) : 0) : totalNonCoupe();
    const voulu = total ? '(' + (total > 99 ? '99+' : total) + ') ' + base : base;
    if (document.title !== voulu) { titreEnCours = true; document.title = voulu; titreEnCours = false; }

    const badge = String(totalNonCoupe());
    if (document.documentElement.getAttribute('data-np-badge') !== badge) document.documentElement.setAttribute('data-np-badge', badge);
  }

  function fermerPanneau() {
    debrancherMenu(true);
    if (panneau) panneau.remove();
    panneau = null;
    placerPile();
    document.removeEventListener('mousedown', clicDehors, true);
    document.removeEventListener('keydown', echap, true);
  }
  function clicDehors(e) {
    if (clicSimule || !panneau || panneau.contains(e.target) || (bouton && bouton.contains(e.target))) return;
    fermerPanneau();
  }
  function echap(e) { if (e.key === 'Escape') fermerPanneau(); }

  function ouvrirPanneau() {
    fermerPanneau();
    panneau = document.createElement('div');
    panneau.setAttribute('data-np-panneau', '');
    panneau.style.cssText = 'position:fixed;z-index:10001;width:' + (filPresent() ? 384 : 360) + 'px;max-width:calc(100vw - 16px);max-height:70vh;display:flex;flex-direction:column;' +
      'background:var(--dropdown-menu-bg,#282A2E);color:var(--text-color,#C5C8C6);border:1px solid var(--dropdown-menu-border,#373B41);border-radius:8px;' +
      'box-shadow:0 8px 28px rgba(0,0,0,.5);font-size:13px;overflow:hidden;';

    ['click', 'mousedown', 'mouseup', 'pointerdown', 'pointerup', 'touchstart', 'touchend'].forEach(function (t) {
      panneau.addEventListener(t, function (e) { e.stopPropagation(); });
    });
    document.body.appendChild(panneau);
    const forumDispo = !!trouverClocheSite();
    if (ongletPanneau === 'forum' && !forumDispo) ongletPanneau = 'suivis';
    const parTypeOuv = nouveauxParType();
    if (R().ongletOuverture === 1 && forumDispo) ongletPanneau = 'forum';
    else if (R().ongletOuverture === 2) ongletPanneau = 'suivis';
    else if (R().ongletOuverture === 3) ongletPanneau = 'favoris';
    else if (R().ongletOuverture === 4) ongletPanneau = 'mp';
    else if (R().ongletOuverture === 5 && filPresent()) ongletPanneau = 'fil';
    else if (R().ongletOuverture === 0) {
      if (forumDispo && compteSite()) ongletPanneau = 'forum';
      else if (parTypeOuv.topic) ongletPanneau = 'suivis';
      else if (parTypeOuv.favori) ongletPanneau = 'favoris';
      else if (compteMp()) ongletPanneau = 'mp';
      else if (compteFil()) ongletPanneau = 'fil';
    }
    if (ongletPanneau === 'reglages') ongletPanneau = forumDispo ? 'forum' : 'suivis';
    if (ongletPanneau === 'fil' && !filPresent()) ongletPanneau = 'suivis';
    dessinerPanneau();
    placerPanneau();
    setTimeout(function () {
      document.addEventListener('mousedown', clicDehors, true);
      document.addEventListener('keydown', echap, true);
    }, 0);

    verifier(true);
    synchroniserFavoris(false);
    verifierMp();
    if (filPresent()) commandeFil({ a: 'veiller' });
  }

  function placerPanneau() {
    if (!panneau || !bouton) return;
    const r = bouton.getBoundingClientRect();
    const largeur = panneau.offsetWidth;
    panneau.style.top = (r.bottom + 8) + 'px';

    const x = coteCloche() === 'left' ? r.left : r.right - largeur;
    panneau.style.left = Math.max(8, Math.min(x, window.innerWidth - largeur - 8)) + 'px';
    placerPile();
  }

  function el(tag, css, texte) {
    const e = document.createElement(tag);
    if (css) e.style.cssText = css;
    if (texte != null) e.textContent = texte;
    return e;
  }
  const CSS_BTN = 'background:var(--button-color,#373B41);color:var(--button-text-color,#C5C8C6);border:none;border-radius:4px;padding:4px 10px;cursor:pointer;font-size:12px;';

  function dessinerPanneau() {
    if (!panneau) return;
    const defilement = panneau.querySelector('[data-np-corps]');
    const haut = defilement ? defilement.scrollTop : 0;
    panneau.textContent = '';

    const tete = el('div', 'display:flex;align-items:center;gap:4px;padding:8px 10px;border-bottom:1px solid var(--dropdown-menu-border,#373B41);');
    const onglets = [];
    const parType = nouveauxParType();
    if (trouverClocheSite()) onglets.push(['forum', 'Forum', [['messages', compteSite()]]]);
    onglets.push(['suivis', 'Suivis', [['topic', parType.topic]]]);
    onglets.push(['favoris', 'Favoris', [['favori', parType.favori]]]);
    onglets.push(['mp', 'MP', [['mp', compteMp()]]]);
    if (filPresent()) onglets.push(['fil', 'Fil', [['fil', compteFil()]]]);
    onglets.push(['reglages', '⚙', []]);
    onglets.forEach(function (o) {
      const actif = ongletPanneau === o[0];
      const t = el('span', 'cursor:pointer;padding:3px ' + (onglets.length > 5 ? 6 : 8) + 'px;border-radius:4px;display:inline-flex;align-items:center;gap:5px;white-space:nowrap;' +
        (actif ? 'background:var(--button-color,#373B41);color:var(--button-text-color,#C5C8C6);' : 'opacity:.75;'), o[1]);
      t.setAttribute('data-np-onglet', o[0]);
      if (o[0] === 'reglages') t.title = 'Réglages';
      if (o[0] === 'suivis') t.title = 'Topics suivis avec « Suivre »';
      if (o[0] === 'favoris') t.title = 'Tes Sujets favoris';
      if (o[0] === 'mp') t.title = 'Messages privés';
      if (o[0] === 'fil') t.title = 'Blogs suivis (Fil+)';
      o[2].forEach(function (x) {
        if (x[1]) t.appendChild(el('span', stylePastille(x[0]) + 'border-radius:8px;padding:0 5px;font-size:10px;font-weight:bold;line-height:15px;', x[1] > 99 ? '99+' : String(x[1])));
      });
      t.addEventListener('click', function () { changerOnglet(o[0]); });
      tete.appendChild(t);
    });
    tete.appendChild(el('span', 'flex:1;'));
    const dnd = el('span', 'cursor:pointer;padding:1px 5px;border-radius:4px;font-size:13px;line-height:18px;' +
      (R().dnd ? 'background:var(--button-color,#373B41);' : 'opacity:.55;filter:grayscale(1);'), '🌙');
    dnd.setAttribute('data-np-dnd', '');
    dnd.title = R().dnd
      ? 'Ne pas déranger : activé, coupé : ' + texteCoupes() + ' (ni notifications ni pastilles ; les onglets se remplissent quand même). Clic pour désactiver.'
      : 'Ne pas déranger : désactivé. Clic pour couper : ' + texteCoupes() + ' (⚙ pour choisir).';
    dnd.addEventListener('click', basculerDnd);
    tete.appendChild(dnd);
    const rafraichir = el('span', 'cursor:pointer;padding:0 4px;font-size:15px;', '⟳');
    rafraichir.title = 'Vérifier maintenant';
    rafraichir.addEventListener('click', function () {
      verifier(true);
      synchroniserFavoris(true);
      if (ongletPanneau === 'forum') { debrancherMenu(true); setTimeout(function () { if (panneau && ongletPanneau === 'forum') { panneau.removeAttribute('data-np-forum-vu'); dessinerPanneau(); } }, 300); }
    });
    tete.appendChild(rafraichir);
    const x = el('span', 'cursor:pointer;padding:0 4px;', '✕');
    x.title = 'Fermer';
    x.addEventListener('click', fermerPanneau);
    tete.appendChild(x);
    panneau.appendChild(tete);

    const corps = el('div', 'overflow-y:auto;padding:6px 0;');
    corps.setAttribute('data-np-corps', '');
    panneau.appendChild(corps);
    if (ongletPanneau === 'forum') dessinerForum(corps);
    else if (ongletPanneau === 'suivis') dessinerSuivis(corps, 'topic');
    else if (ongletPanneau === 'favoris') dessinerSuivis(corps, 'favori');
    else if (ongletPanneau === 'mp') { dessinerMp(corps); chargerListeMp(false); }
    else if (ongletPanneau === 'fil') dessinerFil(corps);
    else dessinerReglages(corps);
    corps.scrollTop = haut;
  }

  function marquerSuiviLu(id) {
    const s = donnees.suivis[id];
    if (!s || s.dernier == null) return;
    s.vu = s.dernier;
    s.compteVu = s.compte != null ? s.compte : null;
    if (!dejaLus[id] || dejaLus[id].dernier < s.dernier) dejaLus[id] = { dernier: s.dernier, date: Date.now() };
    if (lu.topic === String(id) && s.dernier > lu.dernier) { lu.dernier = s.dernier; lu.ligneA = 0; }
  }

  function barreToutLire(corps, actif, action, aide) {
    const l = el('div', 'display:flex;align-items:center;gap:8px;padding:2px 10px 6px;');
    l.appendChild(el('span', 'flex:1;font-size:11px;opacity:.6;', aide || ''));
    const b = el('button', CSS_BTN + (actif ? '' : 'opacity:.45;cursor:default;'), '✓ Tout lire');
    b.type = 'button';
    b.disabled = !actif;
    b.addEventListener('click', function () { if (actif) action(); });
    l.appendChild(b);
    corps.appendChild(l);
  }

  let annulerSuivis = null;
  function toutFermerSuivis(ids) {
    donnees = lire();
    const entrees = {};
    ids.forEach(function (id) {
      const s = donnees.suivis[id];
      if (!s || s.favori) return;
      entrees[id] = s;
      delete donnees.suivis[id];
    });
    if (!Object.keys(entrees).length) return;
    ecrire();
    if (annulerSuivis) clearTimeout(annulerSuivis.minuteur);

    annulerSuivis = { entrees: entrees, total: 6000, fin: Date.now() + 6000, pause: null, minuteur: 0 };
    armerAnnulerSuivis(6000);
    majLigneNonLus();
    majAffichage();
  }
  function finAnnulerSuivis() { annulerSuivis = null; if (panneau) dessinerPanneau(); }
  function armerAnnulerSuivis(ms) {
    clearTimeout(annulerSuivis.minuteur);
    annulerSuivis.fin = Date.now() + ms;
    annulerSuivis.minuteur = setTimeout(finAnnulerSuivis, ms);
  }
  function annulerFermetureSuivis() {
    if (!annulerSuivis) return;
    clearTimeout(annulerSuivis.minuteur);
    donnees = lire();
    Object.keys(annulerSuivis.entrees).forEach(function (id) { if (!donnees.suivis[id]) donnees.suivis[id] = annulerSuivis.entrees[id]; });
    annulerSuivis = null;
    ecrire();
    majLigneNonLus();
    majAffichage();
  }

  let etatFavoriTopic = '';
  function boutonMenuTopic() {

    const direct = document.querySelector('#topic-top button.menu-btn, #topic-top [title="Plus d\'options"]');
    if (direct) return direct;
    const titre = document.querySelector('#topic-top h1, #topic-top h2, .topic h1, main h1');
    let zone = titre ? titre.parentElement : null;
    for (let n = 0; zone && n < 4; n++, zone = zone.parentElement) {
      const c = Array.from(zone.querySelectorAll('button, [role="button"], span, div, a')).find(function (e) {
        if (e.closest('.post-container, [data-np-panneau], [data-np-bouton], [data-pp], [data-rp-panneau]')) return false;
        const t = (e.textContent || '').trim();
        if (/^[⋮⁝︙…]$|^\.\.\.$/.test(t) && e.children.length <= 1) return true;
        const svg = !t && e.querySelector(':scope > svg');
        return !!(svg && svg.querySelectorAll('circle').length === 3);
      });
      if (c) return c;
    }
    return null;
  }
  function estOptionFavori(t) { return t.length < 30 && /^(ajouter|retirer|enlever|supprimer)\b.{0,12}favoris?$/i.test(t); }
  function affiche(e) { return !!(e && e.isConnected && e.getClientRects().length); }

  function optionFavoriAffichee() {
    const b = boutonMenuTopic();
    const boite = b && b.parentElement;
    if (boite) {
      const items = Array.from(boite.querySelectorAll('.dropdown-item, button, a, li'));
      const o = items.find(function (e) { return e !== b && estOptionFavori((e.textContent || '').trim()); });
      if (o) return affiche(o) ? o : null;
    }
    const o2 = trouverOptionFavori();
    return affiche(o2) ? o2 : null;
  }
  function trouverOptionFavori() {
    const tous = document.querySelectorAll('button, a, li, [role="menuitem"], div, span');
    for (let i = 0; i < tous.length; i++) {
      const e = tous[i];
      if (e.closest('[data-np-panneau], [data-np-pile]')) continue;
      const t = (e.textContent || '').trim();

      if (estOptionFavori(t) && !Array.from(e.children).some(function (c) { return estOptionFavori((c.textContent || '').trim()); })) return e;
    }
    return null;
  }
  function boiteMenu(opt) {
    let e = opt.parentElement;
    while (e && e !== document.body) {
      const p = getComputedStyle(e).position;
      if (p === 'absolute' || p === 'fixed') return e;
      e = e.parentElement;
    }
    return opt.parentElement;
  }
  function cliquer(e, propager) {
    e.dispatchEvent(new MouseEvent('click', { bubbles: !!propager, cancelable: true }));
  }
  function attendre(fn, ms) {
    return new Promise(function (ok) {
      const debut = Date.now();
      (function essai() {
        const v = fn();
        if (v || Date.now() - debut > ms) return ok(v || null);
        setTimeout(essai, 40);
      })();
    });
  }
  let generationFavori = 0;
  let favoriOccupe = false;
  async function basculerFavoriTopic(id, etaitFavori) {
    if (favoriOccupe) return;
    favoriOccupe = true;
    try { await basculerFavoriTopicSuite(id, etaitFavori); }
    finally { setTimeout(function () { favoriOccupe = false; if (panneau) dessinerPanneau(); }, 700); }
  }
  async function basculerFavoriTopicSuite(id, etaitFavori) {
    const bouton = boutonMenuTopic();
    if (!bouton) { finFavori(id, null, 'Menu ⋮ du topic introuvable.'); return; }
    etatFavoriTopic = 'en cours';
    if (panneau) dessinerPanneau();

    let cache = null;
    const guet = new MutationObserver(function () {
      if (cache) return;
      const o = optionFavoriAffichee();
      if (o) { cache = boiteMenu(o); cache.setAttribute('data-np-menu-cache', ''); }
    });
    guet.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class', 'style'] });

    const dejaOuvert = optionFavoriAffichee();
    let opt = dejaOuvert;
    if (!opt) {
      cliquer(bouton, false);
      opt = await attendre(optionFavoriAffichee, 400);
      if (!opt) { cliquer(bouton, true); opt = await attendre(optionFavoriAffichee, 1200); }
    }
    guet.disconnect();
    if (!opt) {
      if (cache) cache.removeAttribute('data-np-menu-cache');
      finFavori(id, null, 'Option « Ajouter en favoris » introuvable dans le menu ⋮.');
      return;
    }
    const retrait = /retir|enlev|supprim/i.test(opt.textContent || '');
    console.log('[Notifications+] Favori : option « ' + (opt.textContent || '').trim() + ' » cliquée (menu ' + (bouton.className || bouton.tagName) + ')');
    cliquer(opt, true);
    setTimeout(function () {

      if (optionFavoriAffichee()) cliquer(bouton, false);
      setTimeout(function () {
        if (optionFavoriAffichee()) cliquer(bouton, true);
        if (cache) cache.removeAttribute('data-np-menu-cache');
      }, 150);
    }, 250);
    favoriSite[id] = { fav: !retrait, date: Date.now() };
    finFavori(id, !retrait, '');
    verifierFavori(id, !retrait, ++generationFavori);
  }

  function verifierFavori(id, voulu, generation) {
    const depart = Date.now();
    const t = setInterval(function () {
      if (generation !== generationFavori) { clearInterval(t); return; }
      if (syncEnCours || relectureDemandee || donnees.syncFavoris < changementFavoriLocal) {
        if (Date.now() - depart > 25000) clearInterval(t);
        return;
      }
      clearInterval(t);
      if (generation !== generationFavori) return;
      const s = lire().suivis[id];
      const estFav = !!(s && s.favori);
      if (estFav !== voulu) {
        console.warn('[Notifications+] Favori : la page Sujets favoris ne montre pas le changement (voulu : ' + (voulu ? 'ajouté' : 'retiré') + ')');
        etatFavoriTopic = 'echec:Le site n\'a pas ' + (voulu ? 'ajouté ce topic à' : 'retiré ce topic de') + ' tes Sujets favoris. Réessaie, ou passe par le menu ⋮ du topic.';
        setTimeout(function () { etatFavoriTopic = ''; if (panneau) dessinerPanneau(); }, 6000);
        if (panneau) dessinerPanneau();
      }
    }, 500);
  }
  function finFavori(id, devientFavori, erreur) {
    if (erreur) {
      console.warn('[Notifications+] Favori : ' + erreur);
      etatFavoriTopic = 'echec:' + erreur;
      setTimeout(function () { etatFavoriTopic = ''; if (panneau) dessinerPanneau(); }, 5000);
      if (panneau) dessinerPanneau();
      return;
    }
    etatFavoriTopic = '';
    changementFavoriLocal = Date.now();
    donnees = lire();
    let s = donnees.suivis[id];
    if (devientFavori) {
      if (!s) {
        const max = maxPostDansPage();
        const vu = lu.topic === String(id) && lu.dernier ? lu.dernier : max;
        s = donnees.suivis[id] = { vu: vu || null, dernier: max || null, compteVu: null, depuis: donnees.dernierGlobal || null };
      }
      s.favori = true;
      s.titre = s.titre || titreTopicCourant();
      const m = location.pathname.match(/^\/topics\/\d+\/([^/?#]+)/);
      if (m) s.slug = m[1];
      donnees.exclus = donnees.exclus.filter(function (x) { return x !== String(id); });
    } else if (s) {
      s.favori = false;
      if (!s.manuel) delete donnees.suivis[id];
    }
    ecrire();
    majLigneNonLus();
    majAffichage();

    setTimeout(function () { synchroniserFavoris(true); }, 1500);
  }

  const favoriSite = {};
  let lectureFavoriEnCours = false;
  async function lireFavoriSite(id) {
    if (lectureFavoriEnCours || favoriOccupe || !estTopicCourant(id)) return;
    const connu = favoriSite[id];
    if (connu && Date.now() - connu.date < 30000) return;
    const bouton = boutonMenuTopic();
    if (!bouton) return;
    lectureFavoriEnCours = true;
    let cache = null;
    try {
      let opt = optionFavoriAffichee();
      const ouvertParNous = !opt;
      if (!opt) {
        const guet = new MutationObserver(function () {
          if (cache) return;
          const o = optionFavoriAffichee();
          if (o) { cache = boiteMenu(o); cache.setAttribute('data-np-menu-cache', ''); }
        });
        guet.observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['class', 'style'] });
        cliquer(bouton, false);
        opt = await attendre(optionFavoriAffichee, 500);
        guet.disconnect();
      }
      if (opt) {
        const fav = /retir|enlev|supprim/i.test(opt.textContent || '');
        favoriSite[id] = { fav: fav, date: Date.now() };
        alignerFavori(id, fav);
      }
      if (ouvertParNous && optionFavoriAffichee()) cliquer(bouton, false);
      await attendre(function () { return !optionFavoriAffichee(); }, 400);
    } finally {
      if (cache) cache.removeAttribute('data-np-menu-cache');
      lectureFavoriEnCours = false;
    }
  }

  function alignerFavori(id, fav) {
    const s = donnees.suivis[id];
    const nous = !!(s && s.favori);
    if (nous === fav) { if (panneau) dessinerPanneau(); return; }
    console.log('[Notifications+] Favori : le site dit ' + (fav ? 'favori' : 'pas favori') + ', mémoire corrigée');
    generationFavori++;
    finFavori(id, fav, '');
  }

  document.addEventListener('click', function (e) {
    if (!e.isTrusted || !e.target || !e.target.closest) return;
    const o = e.target.closest('#topic-top button, #topic-top .dropdown-item, #topic-top li, #topic-top a');
    if (!o || !estOptionFavori((o.textContent || '').trim())) return;
    const id = idTopicCourant();
    if (!id) return;
    const devient = !/retir|enlev|supprim/i.test(o.textContent || '');
    favoriSite[id] = { fav: devient, date: Date.now() };
    generationFavori++;
    if (etatFavoriTopic.indexOf('echec:') === 0) etatFavoriTopic = '';
    setTimeout(function () { finFavori(id, devient, ''); }, 300);
  }, true);

  function dessinerSuivis(corps, type) {

    const idCourant = idTopicCourant();
    if (idCourant && etatFavoriTopic.indexOf('echec:') === 0) {
      corps.appendChild(el('div', 'padding:0 10px 6px;font-size:11px;color:#E0524F;', etatFavoriTopic.slice(6)));
    }
    if (idCourant) {
      const l = el('div', 'display:flex;align-items:center;gap:8px;padding:4px 10px 8px;border-bottom:1px solid var(--dropdown-menu-border,#373B41);margin-bottom:4px;');
      l.appendChild(el('span', 'flex:1;opacity:.8;', 'Ce topic'));
      const suivi = !!donnees.suivis[idCourant];
      const b = el('button', CSS_BTN, suivi ? '🔕 Ne plus suivre' : '🔔 Suivre');
      b.type = 'button';
      b.addEventListener('click', function () { if (suivi) nePlusSuivre(idCourant); else suivreTopicCourant(); });

      const fav = favoriSite[idCourant] ? favoriSite[idCourant].fav : !!(donnees.suivis[idCourant] && donnees.suivis[idCourant].favori);
      if (!favoriOccupe && etatFavoriTopic !== 'en cours') setTimeout(function () { lireFavoriSite(idCourant); }, 0);

      const bf = el('button', CSS_BTN + 'display:inline-flex;align-items:center;gap:4px;' + (fav ? '' : 'opacity:.85;'));
      if (etatFavoriTopic === 'en cours') bf.textContent = '⏳';
      else {
        const etoile = el('span', 'font-size:13px;line-height:1;', fav ? '★' : '☆');
        if (fav) {
          etoile.style.color = couleurType('favori');
          etoile.style.textShadow = '0 0 1px #000,0 0 1px #000,0 0 2px rgba(0,0,0,.8)';
          bf.style.boxShadow = 'inset 0 0 0 1px ' + couleurType('favori');
        }
        bf.appendChild(etoile);
        bf.appendChild(document.createTextNode('Favori'));
      }
      bf.type = 'button';
      bf.setAttribute('data-np-favori-topic', '');
      bf.title = fav ? 'Dans tes Sujets favoris : clic pour le retirer' : 'Ajouter ce topic à tes Sujets favoris (comme « Ajouter en favoris » du menu ⋮ du topic)';
      bf.disabled = etatFavoriTopic === 'en cours' || favoriOccupe;
      if (favoriOccupe) bf.style.cursor = 'progress';
      bf.addEventListener('click', function () { basculerFavoriTopic(idCourant, fav); });
      l.appendChild(bf);
      l.appendChild(b);
      corps.appendChild(l);
    }

    const ids = Object.keys(donnees.suivis).filter(function (id) { return typeSuivi(donnees.suivis[id]) === type; });
    const nbNouveaux = nouveauxParType()[type];
    barreToutLire(corps, nbNouveaux > 0, function () {
      donnees = lire();
      ids.forEach(marquerSuiviLu);
      enregistrerLus();
      ecrire();
      majLigneNonLus();
      majAffichage();
    }, nbNouveaux ? (nbNouveaux > 99 ? '99+' : nbNouveaux) + ' nouveau' + (nbNouveaux > 1 ? 'x' : '') : 'Rien de nouveau');
    if (type === 'topic') {

      const lf = el('div', 'display:flex;align-items:center;gap:6px;padding:0 10px 6px;font-size:11px;');
      lf.setAttribute('data-np-ligne-fermer-suivis', '');
      if (annulerSuivis) {
        const n = Object.keys(annulerSuivis.entrees).length;
        lf.appendChild(el('span', 'opacity:.75;', n + ' topic' + (n > 1 ? 's' : '') + ' retiré' + (n > 1 ? 's' : '') + ' ·'));
        const an = el('span', 'cursor:pointer;text-decoration:underline;', 'Annuler');
        an.setAttribute('data-np-annuler-suivis', '');
        an.addEventListener('click', annulerFermetureSuivis);
        const grp = el('span', 'display:inline-flex;align-items:center;');
        grp.appendChild(an);
        lf.appendChild(grp);
        lf.setAttribute('data-eco-rebours-zone', '');
        const as = annulerSuivis;
        an.setAttribute('data-eco-rebours-total', String(as.total));
        an.setAttribute('data-eco-rebours-fin', String(as.fin));
        if (as.pause != null) an.setAttribute('data-eco-rebours-pause', String(as.pause));
        an.addEventListener('eco-rebours-pause', function () {
          if (annulerSuivis !== as || as.pause != null) return;
          clearTimeout(as.minuteur);
          as.pause = Math.max(0, as.fin - Date.now());
          an.setAttribute('data-eco-rebours-pause', String(as.pause));
        });
        an.addEventListener('eco-rebours-reprise', function () {
          if (annulerSuivis !== as || as.pause == null) return;
          const r = Math.max(800, as.pause);
          as.pause = null;
          an.removeAttribute('data-eco-rebours-pause');
          armerAnnulerSuivis(r);
          an.setAttribute('data-eco-rebours-fin', String(as.fin));
        });
        setTimeout(function () { if (an.isConnected) an.dispatchEvent(new Event('eco-rebours', { bubbles: true })); }, 0);
      }
      lf.appendChild(el('span', 'flex:1;'));
      const bf = el('button', CSS_BTN + (ids.length ? '' : 'opacity:.45;cursor:default;'), '✕ Tout fermer');
      bf.type = 'button';
      bf.disabled = !ids.length;
      bf.title = 'Ne plus suivre aucun des topics de cet onglet (tes Sujets favoris ne sont pas touchés)';
      bf.setAttribute('data-np-tout-fermer-suivis', '');
      bf.addEventListener('click', function () { if (ids.length) toutFermerSuivis(ids); });
      lf.appendChild(bf);
      corps.appendChild(lf);
    }
    if (!ids.length) {
      corps.appendChild(el('div', 'padding:14px 12px;opacity:.75;line-height:1.5;', type === 'favori'
        ? 'Aucun Sujet favori suivi. Ajoute des topics à tes favoris sur le forum (ils sont suivis automatiquement) ; voir aussi ⚙ → Suivre mes Sujets favoris.'
        : 'Aucun topic suivi. Dans un topic, « 🔔 Suivre » ci-dessus l\'ajoute.'));
      return;
    }
    ids.sort(function (a, b) {
      const na = nouveaux(donnees.suivis[a]) ? 1 : 0;
      const nb = nouveaux(donnees.suivis[b]) ? 1 : 0;
      if (na !== nb) return nb - na;
      return (donnees.suivis[b].dernier || 0) - (donnees.suivis[a].dernier || 0);
    });
    ids.forEach(function (id) {
      const s = donnees.suivis[id];
      const k = nouveaux(s);

      const ligne = el('a', 'display:flex;align-items:center;gap:8px;padding:6px 10px;cursor:pointer;color:inherit;text-decoration:none;' + (estTopicCourant(id) ? 'background:rgba(127,127,127,.12);' : ''));
      ligne.href = lienVersLigne(id, s, k);
      ligne.setAttribute('data-np-ligne-topic', id);
      ligne.addEventListener('mouseenter', function () { ligne.style.background = 'var(--dropdown-item-hover,#333)'; });
      ligne.addEventListener('mouseleave', function () { ligne.style.background = estTopicCourant(id) ? 'rgba(127,127,127,.12)' : ''; });
      const icone = el('span', 'flex:none;width:16px;text-align:center;', s.favori ? '⭐' : '🔔');
      icone.title = s.favori ? 'Dans tes Sujets favoris' : 'Suivi avec le bouton Suivre';
      ligne.appendChild(icone);
      const titre = el('span', 'flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;' + (k ? 'font-weight:bold;' : 'opacity:.8;'), s.titre || ('Topic n° ' + id));
      titre.title = s.titre || '';
      ligne.appendChild(titre);
      if (k) {
        ligne.appendChild(el('span', 'flex:none;' + stylePastille(typeSuivi(s)) + 'border-radius:9px;padding:1px 7px;font-size:11px;font-weight:bold;', k === -1 ? 'nouveau' : '+' + k));
      }
      const retirer = el('span', 'flex:none;opacity:.5;padding:0 2px;', '✕');
      retirer.title = s.favori ? 'Ne plus suivre (le topic reste dans tes favoris du site)' : 'Ne plus suivre';
      retirer.addEventListener('mouseenter', function () { retirer.style.opacity = '1'; });
      retirer.addEventListener('mouseleave', function () { retirer.style.opacity = '.5'; });
      retirer.addEventListener('click', function (e) { e.preventDefault(); e.stopPropagation(); nePlusSuivre(id); });
      retirer.addEventListener('auxclick', function (e) { e.preventDefault(); e.stopPropagation(); });
      ligne.appendChild(retirer);
      ligne.addEventListener('click', function (e) {
        if (e.ctrlKey || e.metaKey || e.shiftKey) { ciblePourNouvelOnglet(id, s, k); return; }
        e.preventDefault();
        if (k) ouvrirTopic(id, s); else location.href = lienTopic(id, s);
      });
      ligne.addEventListener('auxclick', function (e) { if (e.button === 1) ciblePourNouvelOnglet(id, s, k); });
      corps.appendChild(ligne);
    });
  }

  function ligneReglage(corps, libelle, controle, aide) {
    const l = el('div', 'padding:6px 12px;');
    const haut = el('div', 'display:flex;align-items:center;gap:8px;');
    haut.appendChild(el('span', 'flex:1;', libelle));
    haut.appendChild(controle);
    l.appendChild(haut);
    if (aide) l.appendChild(el('div', 'font-size:11px;opacity:.6;margin-top:2px;line-height:1.4;', aide));
    corps.appendChild(l);
    return l;
  }
  function caseACocher(cle, apres) {
    const c = document.createElement('input');
    c.type = 'checkbox';
    c.checked = !!R()[cle];
    c.style.cursor = 'pointer';
    c.addEventListener('change', function () {
      donnees = lire();
      donnees.reglages[cle] = c.checked;
      ecrire();
      if (apres) apres(c.checked, c);
      majAffichage();
    });
    return c;
  }
  function liste(cle, options, apres) {
    const s = document.createElement('select');
    s.style.cssText = 'background:#1D1F21;color:#C5C8C6;border:1px solid #373B41;border-radius:4px;padding:2px 4px;';
    options.forEach(function (o) {
      const op = document.createElement('option');
      op.value = String(o[0]);
      op.textContent = o[1];
      if (String(R()[cle]) === String(o[0])) op.selected = true;
      s.appendChild(op);
    });
    s.addEventListener('change', function () {
      donnees = lire();
      donnees.reglages[cle] = Number(s.value);
      ecrire();
      if (apres) apres();
    });
    return s;
  }

  function listeTexte(cle, options, apres) {
    const s = document.createElement('select');
    s.style.cssText = 'background:#1D1F21;color:#C5C8C6;border:1px solid #373B41;border-radius:4px;padding:2px 4px;';
    options.forEach(function (o) {
      const op = document.createElement('option');
      op.value = o[0];
      op.textContent = o[1];
      if (R()[cle] === o[0]) op.selected = true;
      s.appendChild(op);
    });
    s.addEventListener('change', function () {
      donnees = lire();
      donnees.reglages[cle] = s.value;
      ecrire();
      if (apres) apres();
    });
    return s;
  }

