      const bFichier = el('button', CSS_BTN, 'Fichier…');
      bFichier.type = 'button';
      bFichier.addEventListener('click', function () { choix.click(); });
      choix.addEventListener('change', function () {
        const f = choix.files && choix.files[0];
        if (!f) return;
        if (f.size > 2 * 1024 * 1024) { aide.textContent = 'Fichier trop lourd (2 Mo max) : utilise plutôt un lien (Noelshack…).'; return; }
        const lecteur = new FileReader();
        lecteur.onload = function () {
          if (!ecrireMedia(String(lecteur.result))) { aide.textContent = 'Pas assez de place dans le navigateur : utilise plutôt un lien.'; return; }
          reconstruireBouton();
          dessinerPanneau();
        };
        lecteur.readAsDataURL(f);
      });
      boutons.appendChild(bFichier);
