    suiv.title = 'Page suivante';
    const champ = document.createElement('input');
    champ.type = 'number';
    champ.min = '1';
    champ.inputMode = 'numeric';
    champ.title = 'Numéro de la page : tapes-en un autre puis Entrée';
    champ.style.cssText = 'width:52px;height:' + (modele ? Math.max(26, modele.offsetHeight || 30) : 30) + 'px;box-sizing:border-box;margin:0;padding:0 4px;text-align:center;' +
      'font-size:13px;font-weight:600;border:2px solid var(--button-color,#FFB840);border-radius:8px;background:transparent;color:var(--button-color,#FFB840);box-shadow:none;outline:none;';
    const total = document.createElement('span');
