    '.btn.maj:hover svg{transform:rotate(45deg);}',
    '.btn.maj[data-tourne] svg{animation:pp-tour .8s linear infinite;}',
    '@keyframes pp-tour{to{transform:rotate(360deg);}}',

    '.corps{flex:1;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:transparent transparent;}',
    ':host(:hover) .corps{scrollbar-color:color-mix(in srgb,var(--line-color,var(--text-color,#888)) 45%,transparent) transparent;}',
    '.corps::-webkit-scrollbar{width:6px;background:transparent;}',
    '.corps::-webkit-scrollbar-thumb{background:transparent;border-radius:6px;}',
    ':host(:hover) .corps::-webkit-scrollbar-thumb{background:color-mix(in srgb,var(--line-color,var(--text-color,#888)) 45%,transparent);}',
    '.avant,.etat{display:block;width:100%;padding:8px 10px;font-size:11.5px;opacity:.7;text-align:center;}',
    '.avant{cursor:pointer;background:none;border:0;color:inherit;font-family:inherit;}',
    '.avant:hover{opacity:1;text-decoration:underline;}',
    '.l{display:flex;gap:7px;align-items:flex-start;padding:6px 10px 6px 8px;text-decoration:none;color:inherit;',
    'border-bottom:1px solid color-mix(in srgb,var(--list-color,#373B41) 60%,transparent);border-left:3px solid transparent;content-visibility:auto;contain-intrinsic-size:auto 48px;}',
    '.l:hover{background:var(--hover-color,rgba(127,127,127,.15));}',
    '.l[data-courant]{background:color-mix(in srgb,var(--button-color,#FFB840) 16%,transparent);border-left-color:var(--button-color,#FFB840);}',
    '.ic{flex:none;width:22px;display:flex;justify-content:center;}',
    '.ic .d{width:20px;height:auto;margin-top:2px;image-rendering:pixelated;}',
    '.ic .e{font-size:14px;line-height:16px;}',
    '.x{flex:1;min-width:0;}',

    '.mini{width:13px;height:auto;image-rendering:pixelated;vertical-align:-2px;margin-right:4px;font-size:10px;opacity:1;}',
    '.fav{margin-right:4px;}',
    '.pastille{display:inline-block;min-width:16px;height:16px;padding:0 4px;margin-left:5px;border-radius:8px;color:#fff;font:700 10px/16px Arial,sans-serif;text-align:center;vertical-align:1px;box-sizing:border-box;}',
    '.vignette{position:relative;flex:none;display:flex;align-items:center;justify-content:center;overflow:hidden;border-radius:5px;background:rgba(0,0,0,.18);}',
    '.vignette img:not(.icone),.vignette video{width:100%;height:100%;object-fit:cover;display:block;}',
    '.vignette .icone{width:24px;height:auto;opacity:.75;image-rendering:pixelated;}',
