    ':host([data-vue=cartes]) .lignes{display:grid;grid-template-columns:repeat(auto-fill,minmax(var(--pp-col-carte,120px),1fr));gap:8px;padding:8px;}',
    '.l.cartes{flex-direction:column;align-items:stretch;gap:4px;padding:5px 5px 7px;border:1px solid var(--list-color,#373B41);border-radius:7px;background:var(--topic-color-1,rgba(127,127,127,.08));contain-intrinsic-size:auto calc(var(--pp-col-carte,120px) * .72 + 64px);}',
    '.l.cartes[data-courant]{border-color:var(--button-color,#FFB840);border-left-color:var(--button-color,#FFB840);}',
    '.l.cartes .vignette{width:100%;height:calc(var(--pp-col-carte,120px) * .72);}',
    '.l.cartes .vignette img:not(.icone),.l.cartes .vignette video{object-fit:contain;}',
