  function ic0(s) { return iconeCol(s).src ? 'd' : 'e'; }

  function tailleCol() {
    return modeCol() === 'cartes' ? Math.max(100, Math.min(220, Math.round(+reglages.topic.colonneCarte) || 120))
      : Math.max(36, Math.min(96, Math.round(+reglages.topic.colonneVignette) || 56));
  }
  function appliquerModeCol() {
    if (!col.hote) return;
    col.hote.setAttribute('data-vue', modeCol());
    col.hote.style.setProperty('--pp-col-vig', Math.max(36, Math.min(96, Math.round(+reglages.topic.colonneVignette) || 56)) + 'px');
    col.hote.style.setProperty('--pp-col-carte', Math.max(100, Math.min(220, Math.round(+reglages.topic.colonneCarte) || 120)) + 'px');
    if (col.etat && col.etat.vue) col.etat.vue.innerHTML = modeCol() === 'compact' ? SVG_LIGNES : SVG_GRILLE;
  }
  function choisirModeCol(v) {
    if (reglages.topic.colonneVue === v) return;
    reglages.topic.colonneVue = v;
    enregistrer();
    appliquerModeCol();
    dessinerColonne();
    remplirSiCourt();
    majAffichageCol();
  }
  function majAffichageCol() { colAffFns.forEach(function (f) { if (f._el && !f._el.isConnected) colAffFns.delete(f); else f(); }); }
  const colAffFns = new Set();

  const VUES_COL_PP = [
    ['cg', 'Grandes cartes', 'cartes', 200, 'm'],
    ['cp', 'Petites cartes', 'cartes', 120, 'p'],
    ['vg', 'Grandes vignettes', 'vignettes', 80, 'vg'],
    ['vp', 'Petites vignettes', 'vignettes', 44, 'vp'],
    ['compact', 'Compact', 'compact', 0, 'liste'],
  ];
  function tailleCartesCol() { return Math.max(100, Math.min(220, Math.round(+reglages.topic.colonneCarte) || 120)); }
  function tailleVignettesCol() { return Math.max(36, Math.min(96, Math.round(+reglages.topic.colonneVignette) || 56)); }
  function positionCol() {
    const m = modeCol();
    if (m === 'compact') return 4;
    if (m === 'cartes') return Math.max(0, Math.min(1, (200 - tailleCartesCol()) / 80));
    return 2 + Math.max(0, Math.min(1, (80 - tailleVignettesCol()) / 36));
  }
  function ligneActiveCol() {
    const m = modeCol();
    if (m === 'compact') return 4;
    if (m === 'cartes') return tailleCartesCol() >= 160 ? 0 : 1;
    return tailleVignettesCol() >= 62 ? 2 : 3;
  }
  function choisirDePositionCol(pos, final) {
    pos = Math.max(0, Math.min(4, pos));
    if (pos > 3.5) choisirModeCol('compact');
    else if (pos >= 1.5) { reglages.topic.colonneVignette = Math.round(80 - (Math.max(2, Math.min(3, pos)) - 2) * 36); choisirModeCol('vignettes'); }
    else { reglages.topic.colonneCarte = Math.round((200 - Math.max(0, Math.min(1, pos)) * 80) / 5) * 5; choisirModeCol('cartes'); }
    appliquerModeCol();
    if (final) enregistrer();
    majAffichageCol();
  }
  function curseurAffichageCol() {
    const m = document.createElement('div');
    m.style.cssText = 'display:flex;gap:6px;padding:2px 2px 0;user-select:none;';
    const H = 30;
    const piste = document.createElement('div');
    piste.setAttribute(ATTR + '-curseur-colonne', '');
    piste.title = 'Taille des cartes / vignettes (glisser) ; en bas : Compact';
    piste.style.cssText = 'position:relative;width:22px;flex:none;cursor:pointer;border:1px dotted rgba(127,127,127,.6);border-radius:4px;touch-action:none;';
    const rail = document.createElement('div');
    rail.style.cssText = 'position:absolute;left:50%;top:' + (H / 2) + 'px;bottom:' + (H / 2) + 'px;width:4px;margin-left:-2px;border-radius:2px;background:rgba(127,127,127,.35);';
    piste.appendChild(rail);
    VUES_COL_PP.forEach(function (v, k) {
      const c = document.createElement('div');
      c.style.cssText = 'position:absolute;left:50%;width:8px;height:1px;margin-left:-4px;background:rgba(200,200,200,.45);top:' + (k * H + H / 2) + 'px;';
      piste.appendChild(c);
    });
    const pouce = document.createElement('div');
    pouce.style.cssText = 'position:absolute;left:2px;right:2px;height:10px;margin-top:-5px;border-radius:3px;background:var(--button-color,#FFB840);box-shadow:0 1px 3px rgba(0,0,0,.5);';
    piste.appendChild(pouce);
    const lignes = document.createElement('div');
    lignes.style.cssText = 'display:flex;flex-direction:column;flex:1;min-width:170px;';
    const els = VUES_COL_PP.map(function (v) {
      const l = document.createElement('div');
      l.setAttribute(ATTR + '-col-vue', v[0]);
      l.style.cssText = 'display:flex;align-items:center;gap:10px;height:' + H + 'px;padding:0 10px 0 8px;border-radius:5px;cursor:pointer;box-sizing:border-box;border:1px solid transparent;';
      const t = document.createElement('span');
      t.textContent = v[1];
      t.style.cssText = 'flex:1;pointer-events:none;';
      const px = document.createElement('span');
      px.style.cssText = 'font-size:11px;opacity:.55;font-variant-numeric:tabular-nums;pointer-events:none;';
      l.append(pictoVuePP(v[4]), t, px);
      l._px = px;
      l.addEventListener('pointerenter', function () { if (!l._actif) l.style.background = 'rgba(127,127,127,.18)'; });
      l.addEventListener('pointerleave', function () { if (!l._actif) l.style.background = ''; });
      l.addEventListener('pointerdown', function (e) {
        if (e.button !== 0) return;
        e.preventDefault();
        e.stopPropagation();
        if (v[2] === 'cartes') reglages.topic.colonneCarte = v[3];
        if (v[2] === 'vignettes') reglages.topic.colonneVignette = v[3];
        choisirModeCol(v[2]);
        appliquerModeCol();
        enregistrer();
        majAffichageCol();
      });
      lignes.appendChild(l);
      return l;
    });
    function maj() {
      pouce.style.top = (positionCol() * H + H / 2) + 'px';
      const k0 = ligneActiveCol();
      const m0 = modeCol();
      els.forEach(function (l, k) {
        l._actif = k === k0;
        l.style.background = l._actif ? 'rgba(127,127,127,.22)' : '';
        l.style.borderColor = l._actif ? 'var(--button-color,#FFB840)' : 'transparent';
        l._px.textContent = l._actif && m0 !== 'compact' ? (m0 === 'cartes' ? tailleCartesCol() : tailleVignettesCol()) + ' px' : '';
      });
    }
    let tire = false, rPiste = null;
    function suivre(e, final) {
      const r = rPiste || piste.getBoundingClientRect();
      choisirDePositionCol((e.clientY - r.top - H / 2) / H, final);
    }
    piste.addEventListener('pointerdown', function (e) {
      if (e.button !== 0) return;
      e.preventDefault();
      e.stopPropagation();
      tire = true;
      rPiste = piste.getBoundingClientRect();
      try { piste.setPointerCapture(e.pointerId); } catch (er) {  }
      suivre(e, false);
    });
    piste.addEventListener('pointermove', function (e) { if (tire) suivre(e, false); });
    function finir(e) { if (!tire) return; tire = false; suivre(e, true); rPiste = null; }
    piste.addEventListener('pointerup', finir);
    piste.addEventListener('pointercancel', finir);
    maj._el = m;
    colAffFns.add(maj);
    m.append(piste, lignes);
    maj();
    return m;
  }

