  function surPageForumPrincipale() {
    if (Date.now() - memoForum.t < 2000 && memoForum.chemin === location.pathname) return memoForum.v;
    memoForum = { t: Date.now(), chemin: location.pathname, v: !!document.querySelector('button.icon-btn.refresh-btn') };
    return memoForum.v;
  }

  function estActifIci() {
    return actif && (!surPageForumPrincipale() || actifPageForum);
  }

  function estEnTrainDecrire() {
    const zone = document.querySelector('textarea');
    return document.activeElement === zone;
  }

  function actionRafraichir() {
    secondesRestantes = intervalleSec;

    if (!estActifIci()) return;
    if (estEnTrainDecrire()) return;

    if (surPageForumPrincipale()) {
      const champ = document.querySelector('input[placeholder="Rechercher..."]');
      const loupe = champ && champ.parentElement && champ.parentElement.querySelector('button.search-btn');
      const prec = document.querySelector('button.page-nav-btn[title="Page précédente"]:not([data-pp])');
      const page1 = !prec || prec.disabled;
      if (loupe && champ && !champ.value.trim() && page1 && !document.documentElement.hasAttribute('data-pp-filtre')) cliquerActualiser(loupe);
      return;
    }

    const bouton = boutonsActualiser().find(function (b) { return b.classList.contains('refresh-text-btn'); });
    if (bouton) cliquerActualiser(bouton);
  }

  function tickAffichage() {
    if (estActifIci()) secondesRestantes = Math.max(0, secondesRestantes - 1);
    mettreAJourAffichage();
  }

  function demarrerCycle() {
    if (minuteur) clearInterval(minuteur);
    minuteur = setInterval(actionRafraichir, intervalleSec * 1000);
  }

  function demarrer() {
    arreter();
    secondesRestantes = intervalleSec;
    demarrerCycle();
    chrono = setInterval(tickAffichage, 1000);
    mettreAJourAffichage();
  }

  function arreter() {
    if (minuteur) clearInterval(minuteur);
    if (chrono) clearInterval(chrono);
    minuteur = null;
    chrono = null;
  }

  function basculerActif(valeur) {
    actif = valeur;
    GM_setValue('actif', actif);
    if (actif) {
      demarrer();
    } else {
      arreter();
      mettreAJourAffichage();
    }
  }

  function changerIntervalle(nouvelleValeurSec) {
    intervalleSec = nouvelleValeurSec;
    GM_setValue('intervalleSec', intervalleSec);
    if (actif) demarrer();
    else mettreAJourAffichage();
  }

  function mettreEnPausePourMenu() {
    if (minuteur) clearInterval(minuteur);
    if (chrono) clearInterval(chrono);
    minuteur = null;
    chrono = null;

    boutonsActualiser().forEach(function (bouton) {
      const { chronoSpan } = assurerConteneur(bouton);
      definirTexteChrono(chronoSpan, '');
    });
  }

  function reprendreApresMenu() {
    if (actif && !minuteur) demarrer();
  }

  const FX = 'html:not([data-eco-sans-fix-actu]) ';
  const CSS_ROTATION =
    FX + 'button.icon-btn.refresh-btn,' + FX + 'button.icon-btn.refresh-btn:hover,' + FX + 'button.icon-btn.refresh-btn:focus,' + FX + 'button.icon-btn.refresh-btn:active' +
    '{transform:none!important;rotate:none!important;animation:none!important;}' +
    FX + 'button.icon-btn.refresh-btn>svg{transition:transform .2s ease;}' +
    FX + 'button.icon-btn.refresh-btn:hover>svg{transform:rotate(90deg);}';
  const CSS_ROTATION_REGLAGES = FX + 'button.icon-btn.refresh-btn:has(>.auto-refresh-controle:hover)>svg{transform:none;}';
  const styleRotation = document.createElement('style');
  styleRotation.textContent = CSS_ROTATION + '.auto-refresh-chrono::before{content:attr(data-chrono);}';
  (document.head || document.documentElement).appendChild(styleRotation);

  const styleRotation2 = document.createElement('style');
  styleRotation2.textContent = CSS_ROTATION_REGLAGES;
  (document.head || document.documentElement).appendChild(styleRotation2);

  function assurerConteneur(bouton) {

    if (!bouton._nanaPositionVue) {
      bouton._nanaPositionVue = true;
      if (getComputedStyle(bouton).position === 'static') bouton.style.position = 'relative';
    }

    let controle = bouton.querySelector(':scope > .auto-refresh-controle');
    if (!controle) {
      controle = document.createElement('button');
      controle.type = 'button';
      controle.className = 'auto-refresh-controle';
      controle.title = "Réglages de l'auto-actualisation";

      controle.style.position = 'absolute';
      if (bouton.classList.contains('icon-btn')) {
        controle.style.top = '50%';
        controle.style.right = '100%';
        controle.style.transform = 'translateY(-50%)';
        controle.style.marginRight = '6px';
      } else {
        controle.style.bottom = '100%';
        controle.style.left = '50%';
        controle.style.transform = 'translateX(-50%)';
        controle.style.marginBottom = '6px';
      }
      controle.style.height = '26px';
      controle.style.padding = '0 8px';
      controle.style.display = 'inline-flex';
      controle.style.alignItems = 'center';
      controle.style.justifyContent = 'center';
      controle.style.gap = '6px';
      controle.style.borderRadius = '6px';
      controle.style.border = 'none';
      controle.style.cursor = 'pointer';
      controle.style.background = 'var(--button-color)';
      controle.style.color = 'var(--button-text-color)';
      controle.style.transition = 'background .2s ease';
      controle.style.fontSize = '12px';
      controle.style.whiteSpace = 'nowrap';
      controle.style.zIndex = '10';

      const chronoSpan = document.createElement('span');
      chronoSpan.className = 'auto-refresh-chrono';
      chronoSpan.style.opacity = '0.85';
      controle.appendChild(chronoSpan);

      const modele = bouton.querySelector('svg');
      let icone = null;
      if (modele) {
        const iconeWrap = document.createElement('span');
        iconeWrap.style.position = 'relative';
        iconeWrap.style.display = 'inline-flex';
        iconeWrap.style.alignItems = 'center';
        iconeWrap.style.justifyContent = 'center';
        iconeWrap.style.width = '18px';
        iconeWrap.style.height = '18px';

        icone = modele.cloneNode(true);
        icone.setAttribute('width', '18');
        icone.setAttribute('height', '18');
        icone.style.pointerEvents = 'none';
        icone.style.transition = 'transform .25s ease';
        iconeWrap.appendChild(icone);

        const lettreA = document.createElement('span');
        lettreA.textContent = 'A';
        lettreA.style.position = 'absolute';
        lettreA.style.top = '50%';
        lettreA.style.left = '50%';
        lettreA.style.transform = 'translate(-50%, -50%)';
        lettreA.style.fontSize = '8px';
        lettreA.style.fontWeight = '700';
        lettreA.style.lineHeight = '1';
        lettreA.style.pointerEvents = 'none';
        lettreA.style.color = 'var(--button-text-color)';
        iconeWrap.appendChild(lettreA);

        controle.appendChild(iconeWrap);
      } else {
        const repli = document.createElement('span');
        repli.textContent = '⋮';
        controle.appendChild(repli);
      }

      controle.addEventListener('mouseenter', function () {
        controle.style.background = 'var(--button-hover-color)';
        if (icone) icone.style.transform = 'rotate(90deg)';
      });
      controle.addEventListener('mouseleave', function () {
        controle.style.background = 'var(--button-color)';
        if (icone) icone.style.transform = 'rotate(0deg)';
      });
      controle.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();
        ouvrirMenu(controle);
      });

      bouton.appendChild(controle);
    }

    const chronoSpan = controle.querySelector('.auto-refresh-chrono');
    return { chronoSpan, dots: controle };
  }

  function definirTexteChrono(chronoSpan, texte) {
    if (chronoSpan.getAttribute('data-chrono') !== texte) chronoSpan.setAttribute('data-chrono', texte);
    if (chronoSpan.firstChild) chronoSpan.textContent = '';
    const d = texte ? 'inline' : 'none';
    if (chronoSpan.style.display !== d) chronoSpan.style.display = d;
  }

  function mettreAJourAffichage() {
    boutonsActualiser().forEach(function (bouton) {
      const { chronoSpan } = assurerConteneur(bouton);
      definirTexteChrono(chronoSpan, estActifIci() ? '(' + secondesRestantes + 's)' : '');
    });
  }

  let menu = null;

  let ancreMenu = null;
  let observateurMenu = null;

  function boutonMenuVisible() {
    if (!ancreMenu || !ancreMenu.isConnected) return false;
    const r = ancreMenu.getBoundingClientRect();
    if (!r.width || !r.height) return false;
    const x = r.left + r.width / 2;
    const y = r.top + r.height / 2;
    if (x < 0 || y < 0 || x > window.innerWidth || y > window.innerHeight) return false;
    const pe = menu ? menu.style.pointerEvents : '';
    if (menu) menu.style.pointerEvents = 'none';
    const dessus = document.elementFromPoint(x, y);
    if (menu) menu.style.pointerEvents = pe;
    return !!dessus && ancreMenu.contains(dessus);
  }

  function positionnerMenu() {
    if (!menu || !ancreMenu) return;

    if (!boutonMenuVisible()) { fermerMenu(); return; }
    const marge = 8;
    const haut = window.innerHeight;
    const r = ancreMenu.getBoundingClientRect();
    menu.style.boxSizing = 'border-box';
    menu.style.maxHeight = (haut - 2 * marge) + 'px';
    menu.style.overflowY = 'auto';
    const h = menu.offsetHeight;
    const l = menu.offsetWidth;
    const placeDessous = haut - r.bottom - 4 - marge;
    const placeDessus = r.top - 4 - marge;
    const boutonVisible = r.bottom > 0 && r.top < haut;
    let top;
    if (h <= placeDessous) top = r.bottom + 4;
    else if (h <= placeDessus) top = r.top - 4 - h;
    else if (boutonVisible) {

      top = placeDessous >= placeDessus ? haut - marge - h : marge;
      top = Math.max(marge, Math.min(top, haut - marge - h));
    } else {

      top = r.top < 0 ? r.bottom + 4 : r.top - 4 - h;
    }
    let gauche = Math.min(r.left, window.innerWidth - l - marge);
    gauche = Math.max(marge, gauche);
    menu.style.top = Math.round(top) + 'px';
    menu.style.left = Math.round(gauche) + 'px';
  }

  function fermerMenu() {
    if (observateurMenu) { observateurMenu.disconnect(); observateurMenu = null; }
    window.removeEventListener('resize', positionnerMenu);
    window.removeEventListener('scroll', positionnerMenu, true);
    ancreMenu = null;
    if (menu) {
      menu.remove();
      menu = null;
      document.removeEventListener('click', fermerMenuSiExterieur, true);
      reprendreApresMenu();
    }
  }

  let clicInterne = false;
  function fermerMenuSiExterieur(e) {
    if (clicInterne) return;

    if (menu && ancreMenu && ancreMenu.contains(e.target)) {
      e.preventDefault();
      e.stopPropagation();
      fermerMenu();
      return;
    }
    if (menu && !menu.contains(e.target)) fermerMenu();
  }

  function ouvrirMenu(ancre) {
    fermerMenu();

    mettreEnPausePourMenu();

    menu = document.createElement('div');
    menu.style.position = 'fixed';
    menu.style.zIndex = '99999';
    menu.style.background = '#282A2E';
    menu.style.border = '1px solid #373B41';
    menu.style.borderRadius = '6px';
    menu.style.padding = '8px';
    menu.style.fontSize = '13px';
    menu.style.color = '#C5C8C6';
    menu.style.boxShadow = '0 2px 8px rgba(0,0,0,0.4)';
    menu.style.minWidth = '220px';

    const ligneToggle = document.createElement('label');
    ligneToggle.style.display = 'flex';
    ligneToggle.style.alignItems = 'center';
    ligneToggle.style.gap = '8px';
    ligneToggle.style.padding = '6px 4px';
    ligneToggle.style.cursor = 'pointer';

    const caseToggle = document.createElement('input');
    caseToggle.type = 'checkbox';
    caseToggle.checked = actif;
    caseToggle.addEventListener('change', function () {
      basculerActif(caseToggle.checked);
    });

    const texteToggle = document.createElement('span');
    texteToggle.textContent = 'Auto-actualisation';

    ligneToggle.appendChild(caseToggle);
    ligneToggle.appendChild(texteToggle);

    const lignePageForum = document.createElement('label');
    lignePageForum.style.display = 'flex';
    lignePageForum.style.alignItems = 'center';
    lignePageForum.style.gap = '8px';
    lignePageForum.style.padding = '6px 4px';
    lignePageForum.style.cursor = 'pointer';

    const casePageForum = document.createElement('input');
    casePageForum.type = 'checkbox';
    casePageForum.checked = actifPageForum;
    casePageForum.addEventListener('change', function () {
      actifPageForum = casePageForum.checked;
      GM_setValue('actifPageForum', actifPageForum);
      mettreAJourAffichage();
    });

    const textePageForum = document.createElement('span');
    textePageForum.textContent = 'Activer sur la liste des sujets';

    lignePageForum.appendChild(casePageForum);
    lignePageForum.appendChild(textePageForum);

    const ligneNotif = document.createElement('label');
    ligneNotif.style.display = 'flex';
    ligneNotif.style.alignItems = 'center';
    ligneNotif.style.gap = '8px';
    ligneNotif.style.padding = '6px 4px';
    ligneNotif.style.cursor = 'pointer';

    const caseNotif = document.createElement('input');
    caseNotif.type = 'checkbox';
    caseNotif.checked = notifTopicActualiseActive;
    caseNotif.addEventListener('change', function () {
      notifTopicActualiseActive = caseNotif.checked;
      GM_setValue('notifTopicActualiseActive', notifTopicActualiseActive);

      document.querySelectorAll('.toast').forEach(traiterToast);
    });

    const texteNotif = document.createElement('span');
    texteNotif.textContent = 'Notification "Topic actualisé"';

    ligneNotif.appendChild(caseNotif);
    ligneNotif.appendChild(texteNotif);

    const blocGif = document.createElement('div');
    blocGif.style.padding = '0 4px 4px 28px';

    const ligneGif = document.createElement('label');
    ligneGif.style.display = 'flex';
    ligneGif.style.alignItems = 'center';
    ligneGif.style.gap = '8px';
    ligneGif.style.padding = '2px 0 6px';
    ligneGif.style.cursor = 'pointer';
    const caseGif = document.createElement('input');
    caseGif.type = 'checkbox';
    caseGif.checked = gifActif;
    const texteGif = document.createElement('span');
    texteGif.textContent = 'Remplacer par un GIF';
    ligneGif.appendChild(caseGif);
    ligneGif.appendChild(texteGif);

    const reglagesGif = document.createElement('div');
    const infoGif = document.createElement('div');
    infoGif.style.fontSize = '11px';
    infoGif.style.color = '#8A8D91';
    infoGif.style.marginBottom = '6px';
    infoGif.style.maxWidth = '240px';
    infoGif.style.wordBreak = 'break-word';

    const styleBouton = function (b) {
      b.type = 'button';
      b.style.background = '#373B41';
      b.style.color = '#C5C8C6';
      b.style.border = '1px solid #373B41';
      b.style.borderRadius = '4px';
      b.style.padding = '4px 10px';
      b.style.cursor = 'pointer';
    };

    const rangeeBoutonsGif = document.createElement('div');
    rangeeBoutonsGif.style.display = 'flex';
    rangeeBoutonsGif.style.gap = '6px';
    rangeeBoutonsGif.style.marginBottom = '6px';
    const boutonFichier = document.createElement('button');
    styleBouton(boutonFichier);
    boutonFichier.textContent = 'Choisir un fichier…';
    const boutonTester = document.createElement('button');
    styleBouton(boutonTester);
    boutonTester.textContent = '▶ Tester';
    rangeeBoutonsGif.appendChild(boutonFichier);

    const favGif = ecoBoutonFavoris(function (url) { champUrl.value = url; validerUrl(); }, 'gif');
    styleBouton(favGif.bouton);
    favGif.bouton.textContent = '⭐ Favoris';
    rangeeBoutonsGif.appendChild(favGif.bouton);

    const selecteur = document.createElement('input');
    selecteur.type = 'file';
    selecteur.accept = 'image/gif';
    selecteur.style.display = 'none';

    const rangeeUrl = document.createElement('div');
    rangeeUrl.style.display = 'flex';
    rangeeUrl.style.gap = '6px';
    const champUrl = document.createElement('input');
    champUrl.type = 'text';
    champUrl.placeholder = 'Lien direct vers un .gif';
    champUrl.style.flex = '1';
    champUrl.style.minWidth = '0';
    champUrl.style.background = '#1D1F21';
    champUrl.style.color = '#C5C8C6';
    champUrl.style.border = '1px solid #373B41';
    champUrl.style.borderRadius = '4px';
    champUrl.style.padding = '4px 6px';
    const boutonUrl = document.createElement('button');
    styleBouton(boutonUrl);
    boutonUrl.textContent = 'OK';
    rangeeUrl.appendChild(champUrl);
    rangeeUrl.appendChild(boutonUrl);

    const ligneVitesse = document.createElement('div');
    ligneVitesse.style.display = 'flex';
    ligneVitesse.style.alignItems = 'center';
    ligneVitesse.style.gap = '6px';
    ligneVitesse.style.marginBottom = '6px';
    const texteVitesse = document.createElement('span');
    texteVitesse.textContent = 'Vitesse';
    texteVitesse.style.minWidth = '52px';
    ligneVitesse.appendChild(texteVitesse);
    ligneVitesse.style.gap = '8px';
    const curseurVitesse = document.createElement('input');
    curseurVitesse.type = 'range';
    curseurVitesse.min = '0.1';
    curseurVitesse.max = '5';
    curseurVitesse.step = '0.1';
    curseurVitesse.style.flex = '1';
    curseurVitesse.style.minWidth = '0';
    curseurVitesse.style.accentColor = 'var(--button-color, #5C7CAD)';
    curseurVitesse.title = 'Double-clic : vitesse originale (×1)';
    const valeurVitesse = document.createElement('span');
    valeurVitesse.style.minWidth = '96px';
    valeurVitesse.style.whiteSpace = 'nowrap';
    valeurVitesse.style.textAlign = 'right';
    valeurVitesse.title = 'Clic : saisir un multiplicateur (curseur jusqu\'à ×5, saisie sans limite)';
    ligneVitesse.appendChild(curseurVitesse);
    ligneVitesse.appendChild(valeurVitesse);
    function dureeExigee() {
      if (!(gifVerrouAffiche && gifDureeFigee > 0 && gifActif && gifDonnees)) return null;
      try { return { g: gifCourant(), d: gifDureeFigee }; } catch (e) { return null; }
    }

    function vitessePour(g, tours, d) {
      return Math.max(0.001, Math.round(tours * g.dureeMs / d * 1000) / 1000);
    }
    function reglerVitesse(v) {
      gifVitesseNum = Math.max(0.01, Math.round(v * 100) / 100);
      const ex = dureeExigee();
      if (ex) {

        gifTours = Math.min(TOURS_MAX_ABSOLU, Math.max(1, Math.round(ex.d * gifVitesseNum / ex.g.dureeMs)));
        gifVitesseNum = vitessePour(ex.g, gifTours, ex.d);
        GM_setValue('gifToursNotif', gifTours);
      }
      GM_setValue('gifVitesseNum', gifVitesseNum);
      majBlocGif();
    }
    curseurVitesse.addEventListener('input', function () { reglerVitesse(parseFloat(curseurVitesse.value)); });
    curseurVitesse.addEventListener('dblclick', function () { reglerVitesse(1); });
    rendreEditable(valeurVitesse, function () {
      return String(gifVitesseNum).replace('.', ',');
    }, reglerVitesse);
    reglagesGif.appendChild(ligneVitesse);

    const ligneTours = document.createElement('div');
    ligneTours.style.display = 'flex';
    ligneTours.style.alignItems = 'center';
    ligneTours.style.gap = '8px';
    ligneTours.style.marginBottom = '6px';
    const texteTours = document.createElement('span');
    texteTours.textContent = 'Tours';
    texteTours.style.minWidth = '52px';
    const curseurTours = document.createElement('input');
    curseurTours.type = 'range';
    curseurTours.min = '1';
    curseurTours.max = String(MAX_TOURS_GIF);
    curseurTours.step = '1';
    curseurTours.value = String(gifTours);
    curseurTours.style.flex = '1';
    curseurTours.style.minWidth = '0';
    curseurTours.style.accentColor = 'var(--button-color, #5C7CAD)';
    curseurTours.title = 'Double-clic : 1 tour (défaut)';
    const valeurTours = document.createElement('span');
    valeurTours.style.minWidth = '96px';
    valeurTours.style.whiteSpace = 'nowrap';
    valeurTours.style.textAlign = 'right';
    valeurTours.title = 'Clic : saisir un nombre de tours (curseur jusqu\'à ' + MAX_TOURS_GIF + ', saisie sans limite)';
    ligneTours.appendChild(texteTours);
    ligneTours.appendChild(curseurTours);
    ligneTours.appendChild(valeurTours);
    reglagesGif.appendChild(ligneTours);

    const ligneResultat = document.createElement('div');
    ligneResultat.style.display = 'flex';
    ligneResultat.style.alignItems = 'center';
    ligneResultat.style.gap = '8px';
    ligneResultat.style.marginBottom = '6px';
    const texteResultat = document.createElement('span');
    texteResultat.textContent = 'Durée';
    texteResultat.style.minWidth = '52px';
    const detailResultat = document.createElement('span');
    detailResultat.style.flex = '1';
    const valeurResultat = document.createElement('span');
    valeurResultat.style.minWidth = '96px';
    valeurResultat.style.whiteSpace = 'nowrap';
    valeurResultat.style.textAlign = 'right';
    valeurResultat.style.fontWeight = '600';
    ligneResultat.appendChild(texteResultat);
    ligneResultat.appendChild(detailResultat);

    const boutonVerrouAffiche = document.createElement('button');
    boutonVerrouAffiche.type = 'button';
    boutonVerrouAffiche.style.background = 'none';
    boutonVerrouAffiche.style.border = 'none';
    boutonVerrouAffiche.style.cursor = 'pointer';
    boutonVerrouAffiche.style.padding = '0';
    boutonVerrouAffiche.style.fontSize = '12px';
    boutonVerrouAffiche.style.lineHeight = '18px';
    boutonVerrouAffiche.addEventListener('click', function () {
      gifVerrouAffiche = !gifVerrouAffiche;
      GM_setValue('gifVerrouAffiche', gifVerrouAffiche);
      if (gifVerrouAffiche) {
        let g = null;
        try { g = gifCourant(); } catch (e) { g = null; }
        gifDureeFigee = g ? Math.round(dureeLectureGif(g) / 100) * 100 : 0;
        GM_setValue('gifDureeFigee', gifDureeFigee);
        if (g) {
          gifVitesseNum = vitessePour(g, gifTours, gifDureeFigee);
          GM_setValue('gifVitesseNum', gifVitesseNum);
        }
      } else {

        gifVitesseNum = 1;
        gifTours = 1;
        GM_setValue('gifVitesseNum', 1);
        GM_setValue('gifToursNotif', 1);
      }
      majBlocGif();
    });
    const colonneDuree = document.createElement('span');
    colonneDuree.style.display = 'inline-flex';
    colonneDuree.style.justifyContent = 'flex-end';
    colonneDuree.style.minWidth = '96px';
    const blocDuree = document.createElement('span');
    blocDuree.style.display = 'inline-flex';
    blocDuree.style.alignItems = 'center';
    blocDuree.style.gap = '4px';
    blocDuree.style.padding = '1px 5px';
    blocDuree.style.marginRight = '-6px';
    blocDuree.style.border = '1px solid transparent';
    blocDuree.style.borderRadius = '5px';
    valeurResultat.style.minWidth = '0';
    blocDuree.appendChild(boutonVerrouAffiche);
    blocDuree.appendChild(valeurResultat);
    colonneDuree.appendChild(blocDuree);
    ligneResultat.appendChild(colonneDuree);
    reglagesGif.appendChild(ligneResultat);

    let vitesseDepartSaisie = 1;
    rendreEditable(valeurResultat, function () {
      vitesseDepartSaisie = vitesseGif();
      let g = null;
      try { g = gifCourant(); } catch (e) { g = null; }
      return g ? (dureeLectureGif(g) / 1000).toFixed(1).replace('.', ',') : '';
    }, function (sec) {
      let g = null;
      try { g = gifCourant(); } catch (e) { g = null; }
      if (!g) return;
      const cible = Math.max(100, Math.round(sec * 10) * 100);

      if (!gifVerrouAffiche) {
        gifTours = Math.min(TOURS_MAX_ABSOLU, Math.max(1, Math.round(cible * vitesseDepartSaisie / g.dureeMs)));
      }
      gifVitesseNum = Math.max(0.001, Math.round(gifTours * g.dureeMs / cible * 1000) / 1000);
      GM_setValue('gifToursNotif', gifTours);
      GM_setValue('gifVitesseNum', gifVitesseNum);
      if (gifVerrouAffiche) { gifDureeFigee = cible; GM_setValue('gifDureeFigee', cible); }
      majBlocGif();
    });
    valeurResultat.title = 'Clic : saisir la durée voulue en secondes (tours et vitesse s\'ajustent)';

    function afficherResultat() {
      let g = null;
      try { g = gifCourant(); } catch (e) { g = null; }
      ligneResultat.style.display = g ? 'flex' : 'none';
      if (!g) return;
      const sec = function (ms) { return (ms / 1000).toFixed(1).replace('.', ',') + ' s'; };
      valeurResultat.textContent = sec(dureeLectureGif(g));
      boutonVerrouAffiche.textContent = gifVerrouAffiche ? '🔒' : '🔓';
      boutonVerrouAffiche.style.opacity = gifVerrouAffiche ? '1' : '0.5';
      blocDuree.style.borderColor = gifVerrouAffiche ? 'var(--button-color, #5C7CAD)' : 'transparent';
      boutonVerrouAffiche.title = gifVerrouAffiche
        ? 'Durée exigée : Vitesse et Tours s\'accordent avec elle (clic pour déverrouiller)'
        : 'Exiger cette durée : Vitesse et Tours s\'accorderont avec elle';
    }
    function reglerTours(n) {
      gifTours = Math.min(TOURS_MAX_ABSOLU, Math.max(1, Math.round(n)));
      curseurTours.value = String(gifTours);
      GM_setValue('gifToursNotif', gifTours);
      const ex = dureeExigee();
      if (ex) {

        gifVitesseNum = vitessePour(ex.g, gifTours, ex.d);
        GM_setValue('gifVitesseNum', gifVitesseNum);
      }
      majBlocGif();
    }
    curseurTours.addEventListener('input', function () { reglerTours(parseInt(curseurTours.value, 10)); });
    curseurTours.addEventListener('dblclick', function () { reglerTours(1); });
    rendreEditable(valeurTours, function () { return String(gifTours); }, reglerTours);

    reglagesGif.appendChild(infoGif);
    reglagesGif.appendChild(rangeeBoutonsGif);
    reglagesGif.appendChild(favGif.zone);

    reglagesGif.appendChild(rangeeUrl);
    reglagesGif.appendChild(selecteur);

    function rendreEditable(etiquette, lireValeur, appliquer) {
      etiquette.style.cursor = 'text';
      etiquette.classList.add('nanachan-valeur-editable');

      Promise.resolve().then(function () {
        const parent = etiquette.parentNode;
        if (!parent || parent.classList && parent.classList.contains('nanachan-colonne-valeur')) return;
        const colonne = document.createElement('span');
        colonne.className = 'nanachan-colonne-valeur';
        colonne.style.display = 'inline-flex';
        colonne.style.justifyContent = 'flex-end';
        colonne.style.alignItems = 'center';
        colonne.style.minWidth = etiquette.style.minWidth || '0';
        colonne.style.flexShrink = '0';
        parent.insertBefore(colonne, etiquette);
        colonne.appendChild(etiquette);
        etiquette.style.minWidth = '0';
      });
      etiquette.addEventListener('click', ouvrirSaisie);

      function ouvrirSaisie() {
        const champ = document.createElement('input');
        champ.type = 'text';
        champ.inputMode = 'decimal';
        champ.value = lireValeur();
        champ.style.width = '96px';
        champ.style.boxSizing = 'border-box';
        champ.style.marginLeft = 'auto';
        champ.style.background = '#1D1F21';
        champ.style.color = '#C5C8C6';
        champ.style.border = '1px solid var(--button-color, #5C7CAD)';
        champ.style.borderRadius = '4px';
        champ.style.padding = '2px 6px';
        champ.style.textAlign = 'right';
        champ.style.font = 'inherit';
        let fini = false;
        let modifie = false;
        const initial = parseFloat(String(lireValeur()).replace(',', '.'));
        function lireChamp() {
          const brut = champ.value.trim().replace(',', '.').replace(/[^0-9.]/g, '');
          const n = parseFloat(brut);
          return brut && !isNaN(n) ? n : null;
        }
        function fermer(valider) {
          if (fini) return;
          fini = true;
          const n = lireChamp();
          champ.remove();
          etiquette.style.display = '';
          if (valider && n !== null) appliquer(n);
          else if (!valider && modifie && !isNaN(initial)) appliquer(initial);
        }

        champ.addEventListener('input', function () {
          const n = lireChamp();
          if (n === null || n <= 0) return;
          modifie = true;
          appliquer(n);
        });
        champ.addEventListener('keydown', function (e) {
          if (e.key === 'Enter') { e.preventDefault(); fermer(true); }
          else if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); fermer(false); }
        });
        champ.addEventListener('blur', function () { fermer(true); });
        etiquette.style.display = 'none';
        etiquette.parentNode.insertBefore(champ, etiquette);
        champ.focus();
        champ.select();
      }
    }

    const ligneDureeNotif = document.createElement('div');
    ligneDureeNotif.style.display = 'flex';
    ligneDureeNotif.style.alignItems = 'center';
    ligneDureeNotif.style.gap = '8px';
    ligneDureeNotif.style.padding = '2px 0 6px';
    const texteDureeNotif = document.createElement('span');
    texteDureeNotif.textContent = 'Durée';
    texteDureeNotif.style.minWidth = '52px';
    const curseurDuree = document.createElement('input');
    curseurDuree.type = 'range';
    curseurDuree.min = '1000';
    curseurDuree.max = '15000';
    curseurDuree.step = '100';
    curseurDuree.value = String(dureeNotifReglee);
    curseurDuree.style.flex = '1';
    curseurDuree.style.minWidth = '0';
    curseurDuree.style.accentColor = 'var(--button-color, #5C7CAD)';
    const valeurDuree = document.createElement('span');
    valeurDuree.style.minWidth = '96px';
    valeurDuree.style.whiteSpace = 'nowrap';
    valeurDuree.style.textAlign = 'right';
    function afficherDuree() {
      curseurDuree.value = String(dureeNotifReglee);
      valeurDuree.textContent = (dureeNotifReglee / 1000).toFixed(1).replace('.0', '').replace('.', ',') + ' s' +
        (dureeNotifReglee === 4000 ? ' (défaut)' : '');
      valeurDuree.title = 'Clic : saisir une durée (1 à 15 s)';
      curseurDuree.title = 'Double-clic : valeur par défaut (4 s)';
    }
    afficherDuree();
    curseurDuree.addEventListener('input', function () {
      dureeNotifReglee = parseInt(curseurDuree.value, 10);
      afficherDuree();
      majBlocGif();
    });
    curseurDuree.addEventListener('change', function () {
      GM_setValue('dureeNotifMs', dureeNotifReglee);
    });

    function dureeParDefaut() {
      dureeNotifReglee = 4000;
      curseurDuree.value = String(dureeNotifReglee);
      GM_setValue('dureeNotifMs', dureeNotifReglee);
      afficherDuree();
      majBlocGif();
    }
    curseurDuree.addEventListener('dblclick', dureeParDefaut);
    rendreEditable(valeurDuree, function () {
      return (dureeNotifReglee / 1000).toFixed(1).replace('.0', '').replace('.', ',');
    }, function (sec) {
      dureeNotifReglee = Math.min(15000, Math.max(1000, Math.round(sec * 10) * 100));
      curseurDuree.value = String(dureeNotifReglee);
      GM_setValue('dureeNotifMs', dureeNotifReglee);
      afficherDuree();
      majBlocGif();
    });
    ligneDureeNotif.appendChild(texteDureeNotif);
    ligneDureeNotif.appendChild(curseurDuree);
    ligneDureeNotif.appendChild(valeurDuree);
    blocGif.appendChild(ligneDureeNotif);

    const ligneTaille = document.createElement('div');
    ligneTaille.style.display = 'flex';
    ligneTaille.style.alignItems = 'center';
    ligneTaille.style.gap = '8px';
    ligneTaille.style.padding = '2px 0 6px';
    const texteTaille = document.createElement('span');
    texteTaille.textContent = 'Taille';
    texteTaille.style.minWidth = '52px';
    const curseurTaille = document.createElement('input');
    curseurTaille.type = 'range';
    curseurTaille.min = '25';
    curseurTaille.max = '300';
    curseurTaille.step = '5';
    curseurTaille.value = String(tailleNotif);
    curseurTaille.style.flex = '1';
    curseurTaille.style.minWidth = '0';
    curseurTaille.style.accentColor = 'var(--button-color, #5C7CAD)';
    curseurTaille.title = 'Double-clic : valeur par défaut (100 %)';
    const valeurTaille = document.createElement('span');
    valeurTaille.style.minWidth = '96px';
    valeurTaille.style.whiteSpace = 'nowrap';
    valeurTaille.style.textAlign = 'right';
    valeurTaille.title = 'Clic : saisir une taille (25 à 300 %)';
    function reglerTaille(pc) {
      tailleNotif = Math.min(300, Math.max(25, Math.round(pc)));
      curseurTaille.value = String(tailleNotif);
      valeurTaille.textContent = tailleNotif + ' %' + (tailleNotif === 100 ? ' (défaut)' : '');
      GM_setValue('tailleNotif', tailleNotif);
      appliquerTailleNotif();
    }
    reglerTaille(tailleNotif);
    curseurTaille.addEventListener('input', function () {
      reglerTaille(parseInt(curseurTaille.value, 10));

      if (lectureGifEnCours && lectureGifEnCours.toile) {
        try {
          const g = gifCourant();
          const e = echelleGif(g);
          lectureGifEnCours.toile.style.width = Math.round(g.largeur * e) + 'px';
          lectureGifEnCours.toile.style.height = Math.round(g.hauteur * e) + 'px';
        } catch (err) {  }
      }
    });

    curseurTaille.addEventListener('change', function () {
      if (lectureGifEnCours) jouerGif(true);
    });
    curseurTaille.addEventListener('dblclick', function () { reglerTaille(100); });
    rendreEditable(valeurTaille, function () { return String(tailleNotif); }, reglerTaille);
    ligneTaille.appendChild(texteTaille);
    ligneTaille.appendChild(curseurTaille);
    ligneTaille.appendChild(valeurTaille);
    blocGif.appendChild(ligneTaille);

    const ligneOpacite = document.createElement('div');
    ligneOpacite.style.display = 'flex';
    ligneOpacite.style.alignItems = 'center';
    ligneOpacite.style.gap = '8px';
    ligneOpacite.style.padding = '2px 0 6px';
    const texteOpacite = document.createElement('span');
    texteOpacite.textContent = 'Opacité';
    texteOpacite.style.minWidth = '52px';
    const curseurOpacite = document.createElement('input');
    curseurOpacite.type = 'range';
    curseurOpacite.min = '10';
    curseurOpacite.max = '100';
    curseurOpacite.step = '1';
    curseurOpacite.value = String(opaciteNotif);
    curseurOpacite.style.flex = '1';
    curseurOpacite.style.minWidth = '0';
    curseurOpacite.style.accentColor = 'var(--button-color, #5C7CAD)';
    const valeurOpacite = document.createElement('span');
    valeurOpacite.style.minWidth = '96px';
    valeurOpacite.style.whiteSpace = 'nowrap';
    valeurOpacite.style.textAlign = 'right';
    valeurOpacite.textContent = opaciteNotif + ' %' + (opaciteNotif === 100 ? ' (défaut)' : '');
    curseurOpacite.addEventListener('input', function () {
      opaciteNotif = parseInt(curseurOpacite.value, 10);
      valeurOpacite.textContent = opaciteNotif + ' %' + (opaciteNotif === 100 ? ' (défaut)' : '');
      appliquerOpaciteNotif();
    });
    curseurOpacite.addEventListener('change', function () {
      GM_setValue('opaciteNotif', opaciteNotif);
    });
    function opaciteParDefaut() {
      opaciteNotif = 100;
      curseurOpacite.value = '100';
      GM_setValue('opaciteNotif', opaciteNotif);
      valeurOpacite.textContent = opaciteNotif + ' % (défaut)';
      appliquerOpaciteNotif();
    }
    curseurOpacite.addEventListener('dblclick', opaciteParDefaut);
    valeurOpacite.title = 'Clic : saisir une opacité (10 à 100 %)';
    rendreEditable(valeurOpacite, function () { return String(opaciteNotif); }, function (pc) {
      opaciteNotif = Math.min(100, Math.max(10, Math.round(pc)));
      curseurOpacite.value = String(opaciteNotif);
      GM_setValue('opaciteNotif', opaciteNotif);
      valeurOpacite.textContent = opaciteNotif + ' %' + (opaciteNotif === 100 ? ' (défaut)' : '');
      appliquerOpaciteNotif();
    });
    curseurOpacite.title = 'Double-clic : valeur par défaut (100 %)';
    ligneOpacite.appendChild(texteOpacite);
    ligneOpacite.appendChild(curseurOpacite);
    ligneOpacite.appendChild(valeurOpacite);
    blocGif.appendChild(ligneOpacite);

    const ligneHauteur = document.createElement('div');
    ligneHauteur.style.display = 'flex';
    ligneHauteur.style.alignItems = 'center';
    ligneHauteur.style.gap = '8px';
    ligneHauteur.style.padding = '2px 0 6px';
    const texteHauteur = document.createElement('span');
    texteHauteur.textContent = 'Hauteur';
    texteHauteur.style.minWidth = '52px';
    const curseurHauteur = document.createElement('input');
    curseurHauteur.type = 'range';
    curseurHauteur.min = '0';
    curseurHauteur.max = '90';
    curseurHauteur.step = '1';
    curseurHauteur.value = String(hauteurNotif);
    curseurHauteur.style.flex = '1';
    curseurHauteur.style.minWidth = '0';
    curseurHauteur.style.accentColor = 'var(--button-color, #5C7CAD)';
    const valeurHauteur = document.createElement('span');
    valeurHauteur.style.minWidth = '96px';
    valeurHauteur.style.whiteSpace = 'nowrap';
    valeurHauteur.style.textAlign = 'right';
    function texteValeurHauteur() { return hauteurNotif === 0 ? 'En bas (défaut)' : '+' + hauteurNotif + ' % écran'; }
    valeurHauteur.textContent = texteValeurHauteur();
    function reglerHauteur(v, enregistrerAussi) {
      hauteurNotif = Math.min(90, Math.max(0, Math.round(v)));
      curseurHauteur.value = String(hauteurNotif);
      valeurHauteur.textContent = texteValeurHauteur();
      appliquerHauteurNotif();
      if (enregistrerAussi) GM_setValue('hauteurNotif', hauteurNotif);
    }
    curseurHauteur.addEventListener('input', function () { reglerHauteur(parseInt(curseurHauteur.value, 10), false); });
    curseurHauteur.addEventListener('change', function () { GM_setValue('hauteurNotif', hauteurNotif); });
    curseurHauteur.addEventListener('dblclick', function () { reglerHauteur(0, true); });
    curseurHauteur.title = 'Double-clic : en bas (défaut)';
    valeurHauteur.title = 'Clic : saisir une hauteur (0 à 90 % de l\'écran)';
    rendreEditable(valeurHauteur, function () { return String(hauteurNotif); }, function (pc) { reglerHauteur(pc, true); });
    ligneHauteur.appendChild(texteHauteur);
    ligneHauteur.appendChild(curseurHauteur);
    ligneHauteur.appendChild(valeurHauteur);
    blocGif.appendChild(ligneHauteur);

    const rangeeTester = document.createElement('div');
    rangeeTester.style.padding = '0 0 6px';
    rangeeTester.appendChild(boutonTester);
    blocGif.appendChild(rangeeTester);

    blocGif.appendChild(ligneGif);

    const ligneFondus = document.createElement('div');
    ligneFondus.style.display = 'flex';
    ligneFondus.style.alignItems = 'center';
    ligneFondus.style.flexWrap = 'wrap';
    ligneFondus.style.gap = '6px';
    ligneFondus.style.padding = '0 0 6px';
    const labelFondu = document.createElement('label');
    labelFondu.style.display = 'flex';
    labelFondu.style.alignItems = 'center';
    labelFondu.style.gap = '8px';
    labelFondu.style.cursor = 'pointer';
    labelFondu.style.marginRight = '4px';
    const caseFondu = document.createElement('input');
    caseFondu.type = 'checkbox';
    caseFondu.checked = fonduActif;
    const texteFondu = document.createElement('span');
    texteFondu.textContent = 'Fondu';
    labelFondu.appendChild(caseFondu);
    labelFondu.appendChild(texteFondu);
    ligneFondus.appendChild(labelFondu);
    const boutonsFondu = [['in', 'Fade in'], ['inout', 'Fade in + out'], ['out', 'Fade out']].map(function (o) {
      const bf = document.createElement('button');
      styleBouton(bf);
      bf.textContent = o[1];
      bf.style.padding = '1px 6px';
      bf.style.fontSize = '11px';
      bf.addEventListener('click', function () {
        fonduMode = o[0];
        GM_setValue('fonduMode', fonduMode);
        majFondus();
        majBlocGif();
      });
      ligneFondus.appendChild(bf);
      return { m: o[0], el: bf };
    });
    caseFondu.addEventListener('change', function () {
      fonduActif = caseFondu.checked;
      GM_setValue('fonduActif', fonduActif);
      majFondus();
      majBlocGif();
    });
    ligneFondus.style.padding = '8px 0 2px';
    reglagesGif.appendChild(ligneFondus);
    blocGif.appendChild(reglagesGif);

    function majBlocGif(message, erreur) {
      caseGif.disabled = !caseNotif.checked;
      curseurOpacite.disabled = !caseNotif.checked;
      curseurTaille.disabled = !caseNotif.checked;
      caseFondu.disabled = !caseNotif.checked;
      boutonsFondu.forEach(function (x) {
        x.el.style.display = fonduActif ? '' : 'none';
        const choisi = x.m === fonduMode;
        x.el.style.background = choisi ? 'var(--button-color, #5C7CAD)' : '#373B41';
        x.el.style.color = choisi ? 'var(--button-text-color, #fff)' : '#C5C8C6';
        x.el.style.borderColor = choisi ? 'var(--button-color, #5C7CAD)' : '#373B41';
      });
      curseurDuree.disabled = !caseNotif.checked;
      afficherDuree();

      const avecGif = !!(caseGif.checked && gifDonnees);
      ligneDureeNotif.style.display = avecGif ? 'none' : 'flex';
      curseurTours.value = String(Math.max(1, Math.min(MAX_TOURS_GIF, Math.round(gifTours))));
      valeurTours.textContent = formatTours(gifTours) + (gifTours === 1 ? ' (défaut)' : '');
      curseurVitesse.value = String(Math.min(5, gifVitesseNum));
      afficherResultat();
      valeurVitesse.textContent = formatVitesse(gifVitesseNum) + (gifVitesseNum === 1 ? ' (défaut)' : '');

      const vitesseAuto = !!(gifVerrouAffiche && gifDureeFigee > 0);
      curseurVitesse.disabled = vitesseAuto || !caseNotif.checked;
      ligneVitesse.style.opacity = vitesseAuto ? '0.55' : '1';
      valeurVitesse.style.pointerEvents = vitesseAuto ? 'none' : '';
      valeurVitesse.classList.toggle('nanachan-valeur-inactive', vitesseAuto);
      curseurVitesse.title = vitesseAuto
        ? 'Durée verrouillée : la vitesse s\'ajuste toute seule au nombre de tours'
        : 'Double-clic : vitesse originale (×1)';
      blocGif.style.opacity = caseNotif.checked ? '1' : '0.45';
      reglagesGif.style.display = (caseGif.checked && caseNotif.checked) ? 'block' : 'none';
      infoGif.textContent = message || descriptionGif();
      infoGif.style.color = erreur ? '#E06C75' : '#8A8D91';
      boutonTester.disabled = !caseNotif.checked;
      boutonTester.style.opacity = caseNotif.checked ? '1' : '0.5';
      boutonTester.title = (gifActif && gifDonnees) ? 'Jouer le GIF' : 'Actualiser le topic pour voir la notification';
    }

    function apresChargement(promesse) {
      majBlocGif('Chargement…');
      promesse.then(function () {

        const ex = dureeExigee();
        if (ex) {
          gifTours = Math.min(TOURS_MAX_ABSOLU, Math.max(1, Math.round(ex.d * vitesseGif() / ex.g.dureeMs)));
          gifVitesseNum = vitessePour(ex.g, gifTours, ex.d);
          GM_setValue('gifToursNotif', gifTours);
          GM_setValue('gifVitesseNum', gifVitesseNum);
        }
        majBlocGif();
        jouerGif(true);
      }).catch(function (e) {
        majBlocGif(e.message, true);
      });
    }

    caseGif.addEventListener('change', function () {
      gifActif = caseGif.checked;
      GM_setValue('gifNotifActif', gifActif);
      majBlocGif();
    });
    caseNotif.addEventListener('change', function () { majBlocGif(); });
    boutonFichier.addEventListener('click', function () { selecteur.click(); });
    selecteur.addEventListener('change', function () {
      const f = selecteur.files && selecteur.files[0];
      if (!f) return;
      apresChargement(f.arrayBuffer().then(function (t) { return enregistrerGif(t, f.name); }));
      selecteur.value = '';
    });
    function validerUrl() {
      const url = champUrl.value.trim();
      if (!/^https?:\/\//i.test(url)) { majBlocGif('Lien invalide (doit commencer par http)', true); return; }
      const nom = decodeURIComponent(url.split(/[?#]/)[0].split('/').pop() || 'GIF');
      apresChargement(telechargerGif(url).then(function (t) {
        enregistrerGif(t, nom);
        champUrl.value = '';
      }));
    }
    boutonUrl.addEventListener('click', validerUrl);
    champUrl.addEventListener('keydown', function (e) { if (e.key === 'Enter') validerUrl(); });
    boutonTester.addEventListener('click', function (e) {
      e.stopPropagation();
      if (gifActif && gifDonnees) { jouerGif(true); return; }

      const bouton = boutonsActualiser()[0];
      if (!bouton) return;
      clicInterne = true;
      try { cliquerActualiser(bouton); } finally { clicInterne = false; }
    });
    majBlocGif();

    const separateur = document.createElement('div');
    separateur.style.borderTop = '1px solid #373B41';
    separateur.style.margin = '6px 0';

    const ligneIntervalle = document.createElement('div');
    ligneIntervalle.style.padding = '6px 4px';

    const labelIntervalle = document.createElement('div');
    labelIntervalle.textContent = "Intervalle d'actualisation";
    labelIntervalle.style.marginBottom = '6px';

    const INTERVALLE_DEFAUT = 15;
    const rangeeChamp = document.createElement('div');
    rangeeChamp.style.display = 'flex';
    rangeeChamp.style.alignItems = 'center';
    rangeeChamp.style.gap = '8px';

    const curseurIntervalle = document.createElement('input');
    curseurIntervalle.type = 'range';
    curseurIntervalle.min = '2';
    curseurIntervalle.max = '120';
    curseurIntervalle.step = '1';
    curseurIntervalle.value = String(Math.min(120, intervalleSec));
    curseurIntervalle.style.flex = '1';
    curseurIntervalle.style.minWidth = '0';
    curseurIntervalle.style.accentColor = 'var(--button-color, #5C7CAD)';
    curseurIntervalle.title = 'Double-clic : valeur par défaut (' + INTERVALLE_DEFAUT + ' s)';

    const valeurIntervalle = document.createElement('span');
    valeurIntervalle.style.minWidth = '96px';
    valeurIntervalle.style.whiteSpace = 'nowrap';
    valeurIntervalle.style.textAlign = 'right';
    valeurIntervalle.title = 'Clic : saisir un intervalle (minimum 2 s)';

    function reglerIntervalle(sec) {
      intervalleSec = Math.min(3600, Math.max(2, Math.round(sec)));
      GM_setValue('intervalleSec', intervalleSec);
      secondesRestantes = intervalleSec;
      curseurIntervalle.value = String(Math.min(120, intervalleSec));
      afficherIntervalle();
    }
    function afficherIntervalle() {
      valeurIntervalle.textContent = intervalleSec + ' s' + (intervalleSec === INTERVALLE_DEFAUT ? ' (défaut)' : '');
    }
    afficherIntervalle();

    curseurIntervalle.addEventListener('input', function () {
      intervalleSec = parseInt(curseurIntervalle.value, 10);
      afficherIntervalle();
    });
    curseurIntervalle.addEventListener('change', function () { reglerIntervalle(intervalleSec); });
    curseurIntervalle.addEventListener('dblclick', function () { reglerIntervalle(INTERVALLE_DEFAUT); });
    rendreEditable(valeurIntervalle, function () { return String(intervalleSec); }, reglerIntervalle);

    rangeeChamp.appendChild(curseurIntervalle);
    rangeeChamp.appendChild(valeurIntervalle);
    ligneIntervalle.appendChild(labelIntervalle);
    ligneIntervalle.appendChild(rangeeChamp);

    menu.appendChild(ligneToggle);
    menu.appendChild(lignePageForum);
    menu.appendChild(ligneNotif);
    menu.appendChild(blocGif);
    menu.appendChild(separateur);
    menu.appendChild(ligneIntervalle);

    document.body.appendChild(menu);

    ancreMenu = ancre;
    positionnerMenu();
    if (!menu) return;
    if (window.ResizeObserver) {
      observateurMenu = new ResizeObserver(positionnerMenu);
      observateurMenu.observe(menu);
    }
    window.addEventListener('resize', positionnerMenu);
    window.addEventListener('scroll', positionnerMenu, true);

    setTimeout(function () {
      document.addEventListener('click', fermerMenuSiExterieur, true);
    }, 0);
  }

  const CLASSE_MASQUAGE_TOAST = 'nanachan-toast-masque';
  const CLASSE_DECALAGE_TOAST = 'nanachan-toast-decale';
  const CLASSE_CROIX_TOAST = 'nanachan-toast-croix';
  const CLASSE_TOAST_TOPIC = 'nanachan-toast-topic';

  let opaciteNotif = GM_getValue('opaciteNotif', 100);

  const styleVarsNotif = document.createElement('style');
  (document.head || document.documentElement).appendChild(styleVarsNotif);
  function majVarsNotif() {
    const css = '.toast-container,.nanachan-gif-notif{--nanachan-opacite-notif:' + (opaciteNotif / 100) +
      ';--nanachan-hauteur-notif:' + hauteurNotif + 'vh;--nanachan-taille-notif:' + (tailleNotif / 100) + ';}';
    if (styleVarsNotif.textContent !== css) styleVarsNotif.textContent = css;
  }
  function appliquerOpaciteNotif() { majVarsNotif(); }

  let hauteurNotif = GM_getValue('hauteurNotif', 0);
  function appliquerHauteurNotif() { majVarsNotif(); }

  let tailleNotif = GM_getValue('tailleNotif', 100);
  function appliquerTailleNotif() { majVarsNotif(); }

  function marquerCroix(toast) {
    if (toast.querySelector('.' + CLASSE_CROIX_TOAST)) return;
    let croix = toast.querySelector('button, [class*="close"], [class*="fermer"], [aria-label]');
    if (!croix) {
      croix = Array.from(toast.querySelectorAll('*')).find(function (e) {
        return /^[✕×✖xX]$/.test((e.textContent || '').trim());
      });
    }
    if (croix) croix.classList.add(CLASSE_CROIX_TOAST);
  }

  function boutonsFlottantsPresents() {
    const pastille = document.querySelector('button[title="Réponse rapide flottante"]');
    if (pastille && pastille.getClientRects().length > 0) return true;
    return Array.from(document.querySelectorAll('.nana-fleche')).some(function (b) {
      return !b.hidden && b.getClientRects().length > 0;
    });
  }

  function majDecalageToast() {
    document.documentElement.classList.toggle(CLASSE_DECALAGE_TOAST, boutonsFlottantsPresents());
  }

  const styleMasquageToast = document.createElement('style');
  styleMasquageToast.textContent = '.toast.' + CLASSE_MASQUAGE_TOAST + '{display:none!important;}' +

    'html.' + CLASSE_DECALAGE_TOAST + ' .toast-container{right:72px!important;left:auto!important;}' +

    '.toast-container,.toast-container .toast,.toast-container .toast *{pointer-events:none!important;}' +
    '.toast.' + CLASSE_TOAST_TOPIC + ',.nanachan-gif-notif{filter:opacity(var(--nanachan-opacite-notif,1));}' +
    '.toast.' + CLASSE_TOAST_TOPIC + '{scale:var(--nanachan-taille-notif,1);transform-origin:100% 100%;translate:0 calc(-1 * var(--nanachan-hauteur-notif,0vh));}' +
    '.toast-container .toast .' + CLASSE_CROIX_TOAST + ',.toast-container .toast .' + CLASSE_CROIX_TOAST + ' *{pointer-events:auto!important;cursor:pointer;}';
  document.head.appendChild(styleMasquageToast);

  function estToastTopicActualise(el) {
    if (!(el instanceof Element)) return false;
    if (!el.classList || !el.classList.contains('toast')) return false;
    const texte = (el.textContent || '').trim();
    return texte.indexOf('Topic actualis') !== -1;
  }

  const TAILLE_MAX_GIF = 128;
  const POIDS_MAX_GIF = 3 * 1024 * 1024;
  let gifActif = GM_getValue('gifNotifActif', false);
  let gifDonnees = GM_getValue('gifNotifDonnees', '');
  let gifNom = GM_getValue('gifNotifNom', '');
  let gifAnalyse = null;
  let lectureGifEnCours = null;

  const FONDU_GIF_MS = 300;
  let dureeNotifReglee = GM_getValue('dureeNotifMs', 4000);
  function dureeNotifMs() { return dureeNotifReglee; }

  const styleValeurs = document.createElement('style');
  styleValeurs.textContent =
    '.nanachan-valeur-editable{background:rgba(0,0,0,.22);border:1px solid #4A4E55;border-radius:4px;' +
    'padding:1px 6px;box-sizing:border-box;transition:border-color .15s ease;}' +
    '.nanachan-valeur-editable:hover{border-color:var(--button-color,#5C7CAD);}' +
    '.nanachan-valeur-editable.nanachan-valeur-inactive{background:none;border-color:transparent;}';
  document.head.appendChild(styleValeurs);
  const CLASSE_COPIE_TOAST = 'nanachan-toast-copie';

  let fonduActif = GM_getValue('fonduActif', true);
  let fonduMode = GM_getValue('fonduMode', 'inout');
  if (['in', 'inout', 'out'].indexOf(fonduMode) === -1) fonduMode = 'inout';
  let fonduEntree, fonduSortie;
  function majFondus() {
    fonduEntree = fonduActif && fonduMode !== 'out';
    fonduSortie = fonduActif && fonduMode !== 'in';
  }
  majFondus();
  let copieToast = null;

  function retirerCopieToast(immediat) {
    const c = copieToast;
    if (!c) return;
    copieToast = null;
    clearTimeout(c._minuteur);
    if (immediat || !fonduSortie) { c.remove(); return; }
    const t = c.querySelector('.toast');
    if (t) {
      t.style.transition = 'opacity .3s ease, transform .3s ease';
      t.style.opacity = '0';
      t.style.transform = 'translateX(100%)';
    }
    setTimeout(function () { c.remove(); }, 300);
  }

  function afficherCopieToast(original) {
    retirerCopieToast(true);
    const conteneurSite = original.closest('.toast-container');
    const conteneur = conteneurSite ? conteneurSite.cloneNode(false) : document.createElement('div');
    if (!conteneurSite) conteneur.className = 'toast-container';
    conteneur.classList.add(CLASSE_COPIE_TOAST);
    const copie = original.cloneNode(true);
    copie.classList.remove(CLASSE_MASQUAGE_TOAST);
    if (!fonduEntree) copie.style.animation = 'none';
    conteneur.appendChild(copie);
    document.body.appendChild(conteneur);
    majDecalageToast();
    marquerCroix(copie);
    const croix = copie.querySelector('.' + CLASSE_CROIX_TOAST);
    if (croix) croix.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      if (copieToast === conteneur) retirerCopieToast(false);
    });
    copieToast = conteneur;
    conteneur._minuteur = setTimeout(function () {
      if (copieToast === conteneur) retirerCopieToast(false);
    }, dureeNotifReglee);
  }

  function versBase64(tampon) {
    const octets = new Uint8Array(tampon);
    let bin = '';
    for (let i = 0; i < octets.length; i += 0x8000) {
      bin += String.fromCharCode.apply(null, octets.subarray(i, i + 0x8000));
    }
    return btoa(bin);
  }

  function depuisBase64(b64) {
    const bin = atob(b64);
    const octets = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) octets[i] = bin.charCodeAt(i);
    return octets;
  }

  function analyserGif(o) {
    if (o.length < 13 || String.fromCharCode(o[0], o[1], o[2], o[3]) !== 'GIF8') throw new Error('pas un GIF');
    const u16 = function (p) { return o[p] | (o[p + 1] << 8); };
    const gif = { largeur: u16(6), hauteur: u16(8), images: [] };
    const drapeaux = o[10];
    let pos = 13;
    let paletteGlobale = null;
    if (drapeaux & 0x80) {
      const n = 3 * (1 << ((drapeaux & 7) + 1));
      paletteGlobale = o.subarray(pos, pos + n);
      pos += n;
    }
    function sousBlocs() {
      const morceaux = [];
      let total = 0;
      while (pos < o.length) {
        const n = o[pos++];
        if (!n) break;
        morceaux.push(o.subarray(pos, pos + n));
        total += n;
        pos += n;
      }
      const res = new Uint8Array(total);
      let k = 0;
      morceaux.forEach(function (m) { res.set(m, k); k += m.length; });
      return res;
    }
    let controle = null;
    while (pos < o.length) {
      const b = o[pos++];
      if (b === 0x21) {
        const etiquette = o[pos++];
        if (etiquette === 0xF9) {
          const taille = o[pos];
          const p = o[pos + 1];
          controle = { disposition: (p >> 2) & 7, transparent: (p & 1) ? o[pos + 4] : -1, delai: u16(pos + 2) };
          pos += taille + 1;
        }
        sousBlocs();
      } else if (b === 0x2C) {
        const img = { x: u16(pos), y: u16(pos + 2), l: u16(pos + 4), h: u16(pos + 6) };
        const p = o[pos + 8];
        pos += 9;
        img.palette = paletteGlobale;
        if (p & 0x80) {
          const n = 3 * (1 << ((p & 7) + 1));
          img.palette = o.subarray(pos, pos + n);
          pos += n;
        }
        img.entrelace = !!(p & 0x40);
        img.codeMin = o[pos++];
        img.donnees = sousBlocs();
        img.disposition = controle ? controle.disposition : 0;
        img.transparent = controle ? controle.transparent : -1;

        const d = controle ? controle.delai : 0;
        img.delaiMs = d <= 1 ? 100 : d * 10;
        controle = null;
        if (img.palette && img.l && img.h) gif.images.push(img);
      } else {
        break;
      }
    }
    if (!gif.images.length || !gif.largeur || !gif.hauteur) throw new Error('GIF vide');
    gif.dureeMs = gif.images.reduce(function (t, i) { return t + i.delaiMs; }, 0);
    return gif;
  }

  function decoderLzw(codeMin, donnees, nbPixels) {
    const sortie = new Uint8Array(nbPixels);
    const prefixe = new Int16Array(4096);
    const suffixe = new Uint8Array(4096);
    const pile = new Uint8Array(4097);
    const effacer = 1 << codeMin;
    const fin = effacer + 1;
    for (let i = 0; i < effacer; i++) suffixe[i] = i;
    let tailleCode = codeMin + 1;
    let masque = (1 << tailleCode) - 1;
    let suivant = fin + 1;
    let ancien = -1;
    let premier = 0;
    let bits = 0;
    let tampon = 0;
    let op = 0;
    for (let pos = 0; pos < donnees.length && op < nbPixels; pos++) {
      tampon |= donnees[pos] << bits;
      bits += 8;
      while (bits >= tailleCode && op < nbPixels) {
        let code = tampon & masque;
        tampon >>= tailleCode;
        bits -= tailleCode;
        if (code === effacer) {
          tailleCode = codeMin + 1;
          masque = (1 << tailleCode) - 1;
          suivant = fin + 1;
          ancien = -1;
          continue;
        }
        if (code === fin) return sortie;
        if (ancien === -1) {
          sortie[op++] = suffixe[code];
          ancien = code;
          premier = suffixe[code];
          continue;
        }
        const lu = code;
        let sp = 0;
        if (code >= suivant) { pile[sp++] = premier; code = ancien; }
        while (code > fin) { pile[sp++] = suffixe[code]; code = prefixe[code]; }
        premier = suffixe[code];
        pile[sp++] = premier;
        if (suivant < 4096) {
          prefixe[suivant] = ancien;
          suffixe[suivant] = premier;
          suivant++;
          if ((suivant & masque) === 0 && suivant < 4096) {
            tailleCode++;
            masque = (1 << tailleCode) - 1;
          }
        }
        ancien = lu;
        while (sp > 0 && op < nbPixels) sortie[op++] = pile[--sp];
      }
    }
    return sortie;
  }

  function lignesEntrelacees(h) {
    const ordre = [];
    [[0, 8], [4, 8], [2, 4], [1, 2]].forEach(function (passe) {
      for (let y = passe[0]; y < h; y += passe[1]) ordre.push(y);
    });
    return ordre;
  }

  function gifCourant() {
    if (!gifDonnees) return null;
    if (gifAnalyse && gifAnalyse.cle === gifDonnees) return gifAnalyse.gif;
    const gif = analyserGif(depuisBase64(gifDonnees));
    gifAnalyse = { cle: gifDonnees, gif: gif };
    return gif;
  }

  const MAX_TOURS_GIF = 20;
  const TOURS_MAX_ABSOLU = 1000;

  let gifVitesseNum = GM_getValue('gifVitesseNum', null);
  if (typeof gifVitesseNum !== 'number') {
    const ancienMode = GM_getValue('gifVitesseMode', String(GM_getValue('gifVitesseNotif', 1)));
    gifVitesseNum = ancienMode === 'perso' ? GM_getValue('gifVitessePerso', 1.5) : (Number(ancienMode) || 1);
  }
  gifVitesseNum = Math.max(0.001, Math.round(gifVitesseNum * 1000) / 1000);
  function vitesseGif() { return gifVitesseNum; }
  function formatVitesse(v) {
    return '×' + String(Math.round(v * 100) / 100).replace('.', ',');
  }
  let gifTours = GM_getValue('gifToursNotif', 1);
  gifTours = Math.min(TOURS_MAX_ABSOLU, Math.max(1, Math.round(Number(gifTours) || 1)));

  let gifVerrouAffiche = GM_getValue('gifVerrouAffiche', false);
  let gifDureeFigee = GM_getValue('gifDureeFigee', 0);
  function formatTours(n) {
    const r = Math.round(n * 10) / 10;
    return String(r).replace('.', ',') + ' tour' + (r > 1 ? 's' : '');
  }

  function dureeLectureGif(gif) {
    return Math.max(200, gifTours * gif.dureeMs / vitesseGif());
  }

  function planLecture(gif) {
    const d = dureeLectureGif(gif);
    return { dispo: d, tours: gifTours, dureeTour: gif.dureeMs / vitesseGif(), coupe: true, debutFondu: fonduSortie ? d - FONDU_GIF_MS : Infinity };
  }

  function echelleGif(gif) {
    const base = Math.min(1, TAILLE_MAX_GIF / gif.largeur, TAILLE_MAX_GIF / gif.hauteur);
    return base * tailleNotif / 100;
  }

  function nouvellePreparation(gif) {
    const echelle = echelleGif(gif);
    const nette = Math.min(Math.max(1, echelle) * 2, echelle * Math.min(2, window.devicePixelRatio || 1));
    const lp = Math.max(1, Math.round(gif.largeur * nette));
    const hp = Math.max(1, Math.round(gif.hauteur * nette));
    const pleine = document.createElement('canvas');
    pleine.width = gif.largeur;
    pleine.height = gif.hauteur;
    const ctxPleine = pleine.getContext('2d');
    const tampon = ctxPleine.createImageData(gif.largeur, gif.hauteur);
    return { taille: tailleNotif, gif: gif, echelle: echelle, lp: lp, hp: hp, pleine: pleine, ctx: ctxPleine, tampon: tampon, px: tampon.data, sauvegarde: null, precedente: null, images: [], t: 0, i: 0 };
  }

  function etapePreparation(pr) {
    const gif = pr.gif, px = pr.px, img = gif.images[pr.i];
    const precedente = pr.precedente;
    if (precedente) {
      if (precedente.disposition === 2) {
        for (let y = precedente.y; y < Math.min(precedente.y + precedente.h, gif.hauteur); y++) {
          for (let x = precedente.x; x < Math.min(precedente.x + precedente.l, gif.largeur); x++) {
            const k = (y * gif.largeur + x) * 4;
            px[k] = px[k + 1] = px[k + 2] = px[k + 3] = 0;
          }
        }
      } else if (precedente.disposition === 3 && pr.sauvegarde) {
        px.set(pr.sauvegarde);
      }
    }
    if (img.disposition === 3) pr.sauvegarde = px.slice();
    try {
      const indices = decoderLzw(img.codeMin, img.donnees, img.l * img.h);
      const lignes = img.entrelace ? lignesEntrelacees(img.h) : null;
      const pal = img.palette;
      for (let r = 0; r < img.h; r++) {
        const y = img.y + (lignes ? lignes[r] : r);
        if (y >= gif.hauteur) continue;
        for (let c = 0; c < img.l; c++) {
          const x = img.x + c;
          if (x >= gif.largeur) break;
          const ind = indices[r * img.l + c];
          if (ind === img.transparent) continue;
          const k = (y * gif.largeur + x) * 4;
          px[k] = pal[ind * 3];
          px[k + 1] = pal[ind * 3 + 1];
          px[k + 2] = pal[ind * 3 + 2];
          px[k + 3] = 255;
        }
      }
    } catch (e) {  }
    pr.ctx.putImageData(pr.tampon, 0, 0);
    const petite = document.createElement('canvas');
    petite.width = pr.lp;
    petite.height = pr.hp;
    const cp = petite.getContext('2d');
    cp.imageSmoothingQuality = 'high';
    cp.drawImage(pr.pleine, 0, 0, pr.lp, pr.hp);
    pr.images.push({ toile: petite, debut: pr.t / gif.dureeMs });
    pr.t += img.delaiMs;
    pr.precedente = img;
    pr.i++;
  }

  function finirPreparation(pr) {
    pr.gif.pretes = {
      taille: pr.taille,
      images: pr.images,
      largeur: Math.round(pr.gif.largeur * pr.echelle),
      hauteur: Math.round(pr.gif.hauteur * pr.echelle),
      lp: pr.lp,
      hp: pr.hp,
    };
    pr.gif.preparation = null;
    return pr.gif.pretes;
  }

  function preparationEnCours(gif) {
    if (!gif.preparation || gif.preparation.taille !== tailleNotif) gif.preparation = nouvellePreparation(gif);
    return gif.preparation;
  }

  function imagesPretes(gif) {
    if (gif.pretes && gif.pretes.taille === tailleNotif) return gif.pretes;
    const pr = preparationEnCours(gif);
    while (pr.i < gif.images.length) etapePreparation(pr);
    return finirPreparation(pr);
  }

  const auRepos = window.requestIdleCallback
    ? function (f) { window.requestIdleCallback(f, { timeout: 4000 }); }
    : function (f) { setTimeout(function () { f({ timeRemaining: function () { return 8; } }); }, 200); };

  function preparerEnFond() {
    auRepos(function (dl) {
      try {
        if (!gifActif || !gifDonnees) return;
        const gif = gifCourant();
        if (!gif) return;
        auRepos(function suite(dl2) {
          try {
            if (gif.pretes && gif.pretes.taille === tailleNotif) return;
            const pr = preparationEnCours(gif);
            do { etapePreparation(pr); } while (pr.i < gif.images.length && dl2.timeRemaining() > 6);
            if (pr.i >= gif.images.length) finirPreparation(pr);
            else auRepos(suite);
          } catch (e) {  }
        });
      } catch (e) {  }
    });
  }

  function positionGif(el) {
    el.style.right = (boutonsFlottantsPresents() ? 72 : 20) + 'px';
  }

  function jouerGif(recommencer) {
    if (lectureGifEnCours) {
      if (!recommencer) return;
      lectureGifEnCours.toile.remove();
      lectureGifEnCours = null;
    }
    let gif, pretes;
    try {
      gif = gifCourant();
      if (!gif) return;
      pretes = imagesPretes(gif);
    } catch (e) { return; }
    const plan = planLecture(gif);

    const toile = document.createElement('canvas');
    toile.width = pretes.lp;
    toile.height = pretes.hp;
    toile.className = 'nanachan-gif-notif';
    toile.style.cssText = 'position:fixed;bottom:calc(16px + var(--nanachan-hauteur-notif, 0vh));z-index:9999;pointer-events:none;transition:opacity ' + FONDU_GIF_MS + 'ms ease;' +
      'width:' + pretes.largeur + 'px;height:' + pretes.hauteur + 'px;';
    positionGif(toile);

    if (fonduEntree) {
      toile.style.opacity = '0';
      document.body.appendChild(toile);
      toile.getBoundingClientRect();
      requestAnimationFrame(function () {
        if (!lectureGifEnCours || lectureGifEnCours.toile !== toile || lectureGifEnCours.fondu) return;
        toile.style.opacity = '1';
      });
    } else {
      document.body.appendChild(toile);
    }
    const ctx = toile.getContext('2d');

    const lecture = { toile: toile };
    lectureGifEnCours = lecture;
    const debut = performance.now();
    let affichee = -1;

    function dessiner(n) {
      if (n === affichee) return;
      affichee = n;
      ctx.clearRect(0, 0, toile.width, toile.height);
      ctx.drawImage(pretes.images[n].toile, 0, 0);
    }

    function terminer() {
      toile.style.opacity = '0';
      setTimeout(function () {
        toile.remove();
        if (lectureGifEnCours === lecture) lectureGifEnCours = null;
      }, FONDU_GIF_MS);
    }

    function image() {
      if (!toile.isConnected) { if (lectureGifEnCours === lecture) lectureGifEnCours = null; return; }
      const ecoule = performance.now() - debut;
      if (plan.coupe && !lecture.fondu && ecoule >= plan.debutFondu) {
        lecture.fondu = true;
        toile.style.opacity = '0';
      }
      if (ecoule >= plan.dispo) {
        if (plan.coupe) {
          toile.remove();
          if (lectureGifEnCours === lecture) lectureGifEnCours = null;
          return;
        }
        dessiner(pretes.images.length - 1);
        terminer();
        return;
      }
      const fraction = (ecoule % plan.dureeTour) / plan.dureeTour;
      let n = 0;
      while (n + 1 < pretes.images.length && pretes.images[n + 1].debut <= fraction) n++;
      dessiner(n);
      requestAnimationFrame(image);
    }
    dessiner(0);
    requestAnimationFrame(image);
  }

