    const champ = rail.querySelector('[data-ip-rail-px]');
    if (document.activeElement !== champ && !reglage) {
      const v = t.code > GAB_ORIGINALE && !ouverte ? String(t.code) : '';
      if (champ.value !== v) champ.value = v;
      const ph = String(coteAffiche(el));
      if (champ.placeholder !== ph) champ.placeholder = ph;
    }
    const plus = rail.querySelector('[data-action="plus"]');
    plus.disabled = !estVideo(el) && !el.hasAttribute(GAB_ATTR_SITE) && coteNaturel(el) > 0 && coteAffiche(el) >= coteNaturel(el) - 1;
    const pli = rail.querySelector('[data-action="pli"]');
