  function decouperMots(texte) {
    const res = [];
    const re = /(-?)"([^"]+)"|(-?)([^\s"]+)/g;
    let m;
    while ((m = re.exec(texte || ''))) {
      const exclu = !!(m[1] || m[3]);
      const mot = (m[2] || m[4] || '').trim();
      if (!mot || mot === '-') continue;
      res.push({ mot: normaliser(mot), brut: mot, exclu: exclu, exact: !!m[2] });
    }
    return res;
  }
