  const UNITES_MS = { s: 1e3, sec: 1e3, min: 6e4, h: 36e5, j: 864e5, mois: 30 * 864e5, an: 365 * 864e5 };

  function deltaEnMs(texte) {
    const m = String(texte || '').match(/(\d+)\s*(sec|s|min|h|j|mois|an)/i);
    return m ? parseInt(m[1], 10) * UNITES_MS[m[2].toLowerCase()] : 0;
  }

  function horodater(liste, maintenant) {
    liste.forEach(function (s) { s._depuis = maintenant - deltaEnMs(s.last_post_delta); });
    return liste;
  }

  function deltaAffiche(s) {
    if (!s._depuis) return s.last_post_delta || '';
    const ms = Math.max(0, Date.now() - s._depuis);
    if (ms < 36e5) return Math.max(1, Math.floor(ms / 6e4)) + 'min';
    if (ms < 864e5) return Math.floor(ms / 36e5) + 'h';
    return Math.floor(ms / 864e5) + 'j';
  }

