  function memoriserMots() {
    try { sessionStorage.setItem(CLE_MOTS_CLES, JSON.stringify(motsCles)); } catch (e) {  }
  }

  function decouperMots(texte) {
    const res = [];
    const re = /(-?)"([^"]+)"|(-?)([^\s"]+)/g;
    let m;
    while ((m = re.exec(texte || ''))) {
      const exclu = !!(m[1] || m[3]);
      const mot = (m[2] || m[4] || '').trim();
      if (!mot) continue;
      const exact = !!m[2];
      res.push({ mot: normaliser(mot), exclu: exclu, exact: exact, brut: (exclu ? '-' : '') + (exact ? '"' + mot + '"' : mot) });
    }
    return res;
  }

  const cacheRegex = new Map();
  function correspond(titre, m) {
    if (!m.exact) return titre.indexOf(m.mot) !== -1;
    let re = cacheRegex.get(m.mot);
    if (!re) {
      const echappe = m.mot.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      re = new RegExp('(^|[^a-z0-9])' + echappe + '($|[^a-z0-9])');
      cacheRegex.set(m.mot, re);
    }
    return re.test(titre);
  }

  function champMots() {
    const barre = document.getElementById(ID_MOTS);
    return barre && barre.querySelector('input');
  }

  function motsActifs() {
    return motsCles.map(function (b) { return decouperMots(b)[0]; }).filter(Boolean)
      .concat(decouperMots(champMots() ? champMots().value : ''));
  }

  let pseudoExact = null;

  const memoRecherche = { texte: '', mode: 'sujet' };
  function filtrerBase(liste) {
    const champ = champRecherche();
    if (champ) { memoRecherche.texte = champ.value.trim(); memoRecherche.mode = modeRecherche(); }
    const texte = normaliser(memoRecherche.texte);
    const parPseudo = memoRecherche.mode === 'pseudo';
    const exact = pseudoExact ? normaliser(pseudoExact) : null;
    return liste.filter(function (s) {
      const tags = nomsTags(s);
      const ok = !tags.length || tags.some(function (t) { return !tagsExclus.has(t); });
      if (!ok) return false;
      if (!typeOk(s)) return false;
      if (!texte) return true;
      if (parPseudo) {
        const auteur = normaliser(s.author && s.author.username);
        return exact ? auteur === exact : auteur.indexOf(texte) !== -1;
      }
      return normaliser(s.title).indexOf(texte) !== -1;
    });
  }

  function passeMots(s, mots) {
    const titre = normaliser(s.title);
    return mots.every(function (m) { return correspond(titre, m) !== m.exclu; });
  }

  function filtrer(liste) {
    const mots = motsActifs();
    return filtrerBase(liste).filter(function (s) { return passeMots(s, mots); });
  }

  function majCompteursMots() {
    const pastilles = document.querySelectorAll('#' + ID_MOTS + ' .rp-mot');
    if (!pastilles.length) return;
    const base = idx.sujets ? filtrerBase(idx.sujets) : null;
    const titres = base ? base.map(function (x) { return normaliser(x.title); }) : null;
    pastilles.forEach(function (p) {
      const nb = p.querySelector('.rp-nb');
      if (!nb) return;
      const m = decouperMots(p.dataset.brut)[0];
      if (!titres || !m) { if (nb.textContent !== '…') nb.textContent = '…'; return; }
      let n = 0;
      titres.forEach(function (t) { if (correspond(t, m)) n++; });
      if (nb.textContent !== String(n)) nb.textContent = n;
      nb.title = m.exclu
        ? n + ' sujet' + (n > 1 ? 's' : '') + ' masqué' + (n > 1 ? 's' : '') + ' par ce mot'
        : n + ' sujet' + (n > 1 ? 's' : '') + ' avec ce mot';
    });
  }

