    el.style.cssText = 'position:fixed;z-index:99990;left:0;top:0;width:min(720px, calc(100vw - 16px));box-sizing:border-box;padding:6px;border-radius:10px;' +
      'background:#1F2125;border:1px solid #373B41;box-shadow:0 10px 30px rgba(0,0,0,.55);font-size:13px;';
    const barreFav = document.createElement('div');
