    retourFav.style.cssText = croix.style.cssText;
    croix.style.marginLeft = '0';

    const pictoRetour = etoileDessinee();
    pictoRetour.setAttribute('width', '16');
    pictoRetour.setAttribute('height', '16');
    pictoRetour.style.cssText = 'width:16px;height:16px;display:block;pointer-events:none;';
    retourFav.appendChild(pictoRetour);
    retourFav.addEventListener('mouseenter', function () { retourFav.style.opacity = '1'; retourFav.style.background = 'rgba(127,127,127,.2)'; });
    retourFav.addEventListener('mouseleave', function () { retourFav.style.opacity = '.7'; retourFav.style.background = 'none'; });
    retourFav.addEventListener('click', function (e) {
      e.preventDefault();
      e.stopPropagation();
      revenirAuxFavoris();
    });
    titre.insertBefore(retourFav, croix);
