    const onglets = document.createElement('div');
    onglets.style.cssText = 'display:flex;gap:4px;border-bottom:1px solid #373B41;margin-bottom:4px;flex:none;';
    const panneaux = {};
    const boutonsOnglets = {};
    [['reglages', 'Réglages'], ['favoris', 'Favoris']].forEach(function (o) {
      const b = document.createElement('button');
      b.type = 'button';
      b.textContent = o[1];
      b.style.cssText = 'background:none;border:none;border-bottom:2px solid transparent;color:#C5C8C6;padding:3px 10px 5px;cursor:pointer;font-size:12px;margin-bottom:-1px;';
      b.addEventListener('click', function () { montrerOnglet(o[0]); });
      onglets.appendChild(b);
      boutonsOnglets[o[0]] = b;
      const p = document.createElement('div');
      panneaux[o[0]] = p;
    });
