      if (ar) champs.ar = ar.value;
      ezgifNoter('↳ resize : ' + cw.name + '=' + L + (ch ? ', ' + ch.name + '=' + H : '') + (im ? ', method=' + im.value : ' (méthode introuvable)') + (ar ? ', ar=' + ar.value : ''));
