    const liste = dep.taille.liste;
    let ti = dep.taille.i;
    let fps = dep.fps;
    let meilleur = null;
    let essai = 0;
    let dernier = '';
    let bloqueTaille = false;
    let bloqueFps = false;
    const journal = function (t) { try { console.info('[Uploads+ ezgif auto] ' + t); } catch (e) {  } };

