      const plusGrand = !bloqueTaille && ti > 0;
      const plusFluide = !bloqueFps && fps < dep.fMax;
      const tailleDabord = equilibre >= 0.5 || !plusFluide;
      if (tailleDabord && plusGrand) { ti--; dernier = 'taille'; return convertir(); }
      if (plusFluide) { fps = Math.min(dep.fMax, Math.max(fps + 1, Math.round(fps * 1.3))); dernier = 'fps'; return convertir(); }
