        const type = (x.type || '').toLowerCase();
        if (type === 'file' || type === 'submit' || type === 'button' || type === 'image' || type === 'reset') return;
        if ((type === 'checkbox' || type === 'radio') && !x.checked) return;
        fd.append(x.name, x.value);
