    const pseudo = auteurPost(post);
    if (!pseudo) return;
    const modele = Array.from(menu.querySelectorAll(':scope > button.dropdown-item')).find(function (b) { return !b.classList.contains('danger'); });
    if (!modele) return;

    if (Array.from(menu.querySelectorAll(':scope > button')).some(function (b) { return /^\s*Modifier\s*$/.test(b.textContent); })) return;
    const staff = estStaff(post);
    const b = document.createElement('button');
    b.type = 'button';
    b.className = 'dropdown-item';
