    if (!appFil || pontEtat === 'ok' || pontEtat === 'attente' && Date.now() - dernierEssai < 600) return;
    if (surFil() && appFil.hasAttribute('data-fp')) { pontEtat = 'ok'; return; }
    if (secours() || essaisPont > 25 || Date.now() - dernierEssai < 600) return;
