        fil.appendChild(bouton('⇲ Dissoudre', 'Sortir les Vocaroo du sous-dossier et le supprimer', function () { dissoudre(barre, d, s); }, { classe: 'vp-pil', style: 'margin-left:auto' }));
        liste.appendChild(fil);
