    if (x.jeton) entrees.push({ t: '🗑 Supprimer de Vocaroo', danger: true, titre: 'Efface le son chez Vocaroo (le lien ne marchera plus nulle part)', faire: function () { supprimerVocaroo(loc); } });
    ouvrirMenu(ancre, nomItem(x), entrees);
